-- WABYS curricula, Revision 1.1 (generated by scripts/build-curricula.py from
-- db/curricula/wabys-2026.json; edit the JSON and run the script, do not edit by hand).
--
-- Source: WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)
--
-- Revision 1.1 adds seven programmes from the PVTD occupations (IEL, CSN,
-- RAC, HAM, OEQ, AVE, IEM), the shared Electro-technology Foundation (ETF)
-- and Cross-Program Modules (CPM), and two study systems: A (60 %
-- competence standard) and B (80 % mastery standard, PVTD centres) with a
-- training-unit plan per new programme. The new programmes' trees include
-- the ETF and CPM units they adopt, under their shared codes, so a learner
-- who moves between electrical-family programmes keeps the credit.
-- The programme card (trades.profile) of all fifteen gains the Revision 1.1
-- fields: duration in both systems, PVTD reference occupation, shared units
-- and the System B plan.
SET search_path = vtc, public;

UPDATE trades SET profile = '{"occupation": {"en": "Electrical Installation Technician", "ar": "فني تركيبات كهربائية"}, "overview": {"en": "Prepares Electrical Installation Technicians to plan, install, test, commission and maintain low-voltage electrical systems in residential, commercial and light-industrial buildings, including motor control, building automation and renewable-energy integration. Benchmarked to the German occupation Elektroniker/-in für Energie- und Gebäudetechnik and IEC 60364 practice.", "ar": "يُعدّ البرنامج فنيي التركيبات الكهربائية لتخطيط وتركيب واختبار وتشغيل وصيانة أنظمة الجهد المنخفض في المباني السكنية والتجارية والصناعية الخفيفة، بما في ذلك التحكم في المحركات وأتمتة المباني وتكامل الطاقة المتجددة. مرجعيته المهنة الألمانية Elektroniker/-in für Energie- und Gebäudetechnik وممارسات IEC 60364."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Building electrician, panel builder, maintenance electrician, PV installer, smart-home technician", "ar": "كهربائي مبانٍ، فني تجميع لوحات، كهربائي صيانة، فني تركيب طاقة شمسية، فني منازل ذكية"}, "standards": "IEC 60364, IEC 61439, IEC 60204-1, IEC 62446, NFPA 70E", "equipment": {"en": "Installation booths, motor-control trainers, PLC trainers (Siemens S7-1200), KNX kits, PV training rig, multifunction installation tester", "ar": "كبائن تركيب، وحدات تدريب تحكم المحركات، وحدات PLC، أطقم KNX، منصة طاقة شمسية، جهاز اختبار تركيبات متعدد الوظائف"}, "tracks": [{"en": "Industrial Automation", "ar": "الأتمتة الصناعية"}, {"en": "Smart Buildings", "ar": "المباني الذكية"}, {"en": "Renewable Energy Systems", "ar": "أنظمة الطاقة المتجددة"}], "capstone": {"en": "Design, install and commission a complete electrical system for a small commercial unit: distribution, lighting, power and one automated function (PLC, KNX or PV), drawings and cable calculations, full initial verification, customer handover and a 30-minute technical interview. 80 hours, 40% of the final examination.", "ar": "تصميم وتركيب وتشغيل نظام كهربائي متكامل لوحدة تجارية صغيرة: التوزيع والإنارة والقوى ووظيفة مؤتمتة واحدة (PLC أو KNX أو طاقة شمسية)، والمخططات وحسابات الكابلات، والتحقق الأولي الكامل، والتسليم للعميل، ومقابلة فنية مدتها 30 دقيقة. 80 ساعة، 40% من الامتحان النهائي."}, "duration": {"en": "3 years, 4,800 nominal hours", "ar": "3 سنوات، 4,800 ساعة اسمية"}, "pvtd": null, "adopts": null, "system_b": null, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb
 WHERE program_code = 'ELI';
UPDATE trades SET profile = '{"occupation": {"en": "Automotive Mechatronics Technician", "ar": "فني ميكاترونكس سيارات"}, "overview": {"en": "Prepares Automotive Mechatronics Technicians to service, diagnose and repair passenger cars and light commercial vehicles, covering mechanical, electrical/electronic and hybrid and battery-electric systems. Diagnostic competence and high-voltage safety are central. Benchmarked to the German occupation Kfz-Mechatroniker/-in and OEM dealer training.", "ar": "يُعدّ البرنامج فنيي ميكاترونكس السيارات لخدمة وتشخيص وإصلاح سيارات الركوب والمركبات التجارية الخفيفة، ويغطي الأنظمة الميكانيكية والكهربائية والإلكترونية والهجينة والكهربائية بالبطاريات. الكفاءة في التشخيص وسلامة الجهد العالي محوريتان. مرجعيته المهنة الألمانية Kfz-Mechatroniker/-in وتدريب وكلاء المصنّعين."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Service technician, diagnostic technician, EV/hybrid technician, service advisor (with experience)", "ar": "فني خدمة، فني تشخيص، فني سيارات كهربائية وهجينة، مستشار خدمة (مع الخبرة)"}, "standards": "OEM service procedures, SAE J1979 (OBD-II), ISO 15765 (CAN), ECE R100, DGUV 209-093", "equipment": {"en": "Two-post lifts, engine cutaway and running stands, OEM-level scan tools, oscilloscopes, wheel aligner, A/C recovery station, HV-insulated tool kits, EV training vehicle", "ar": "روافع، محركات مقطعية وتشغيلية، أجهزة تشخيص، راسمات إشارة، جهاز ضبط زوايا، محطة استرجاع غاز التكييف، عدد معزولة للجهد العالي، سيارة كهربائية تدريبية"}, "tracks": [{"en": "Electric & Hybrid Vehicles", "ar": "السيارات الكهربائية والهجينة"}, {"en": "Advanced Diagnostics & ADAS", "ar": "التشخيص المتقدم وأنظمة مساعدة السائق"}, {"en": "Commercial Vehicle Systems", "ar": "أنظمة المركبات التجارية"}], "capstone": {"en": "Complete diagnostic case study on a customer vehicle with at least one electronic/network fault and one mechanical fault (one HV fault for the EV track): customer interview, diagnostic plan, evidenced tests, repair and verification, repair report and estimate, panel presentation. 60 hours, 40% of the final examination.", "ar": "دراسة حالة تشخيصية كاملة على سيارة عميل بها عطل إلكتروني أو شبكي وعطل ميكانيكي على الأقل (وعطل جهد عالٍ لمسار السيارات الكهربائية): مقابلة العميل، خطة التشخيص، اختبارات موثقة، الإصلاح والتحقق، تقرير الإصلاح والتقدير، والعرض أمام اللجنة. 60 ساعة، 40% من الامتحان النهائي."}, "duration": {"en": "3 years, 4,800 nominal hours", "ar": "3 سنوات، 4,800 ساعة اسمية"}, "pvtd": null, "adopts": null, "system_b": null, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb
 WHERE program_code = 'AUT';
UPDATE trades SET profile = '{"occupation": {"en": "Cutting Machine Operator & CNC Machinist", "ar": "مشغل ماكينات قطع وفني تشغيل CNC"}, "overview": {"en": "Prepares Cutting Machine Operators and CNC Machinists to produce precision components from metals and engineering plastics on conventional lathes and mills and CNC turning and machining centres: reading drawings, planning sequences, writing and optimising CNC programs, setting up machines and verifying quality. Benchmarked to the German occupation Zerspanungsmechaniker/-in and ISO GPS.", "ar": "يُعدّ البرنامج مشغلي ماكينات القطع وفنيي CNC لإنتاج مكونات دقيقة من المعادن واللدائن الهندسية على المخارط والفرايز التقليدية ومراكز الخراطة والتشغيل CNC: قراءة الرسومات، وتخطيط التسلسل، وكتابة برامج CNC وتحسينها، وإعداد الماكينات، والتحقق من الجودة. مرجعيته المهنة الألمانية Zerspanungsmechaniker/-in ومواصفات ISO للمنتجات الهندسية."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "CNC operator, CNC setter-programmer, conventional turner/miller, quality inspector, CAM programmer (junior)", "ar": "مشغل CNC، فني إعداد وبرمجة CNC، خراط وفرّاز تقليدي، مفتش جودة، مبرمج CAM (مبتدئ)"}, "standards": "ISO 128 / ISO 129, ISO 286, ISO 1101, ISO 1302 / 21920, ISO 6983, ISO 12100", "equipment": {"en": "Conventional lathes and milling machines, CNC lathe (Fanuc/Siemens control), 3-axis vertical machining center, CAD/CAM software, CNC simulators, metrology lab with CMM", "ar": "مخارط وفرايز تقليدية، مخرطة CNC، مركز تشغيل رأسي ثلاثي المحاور، برمجيات CAD/CAM، محاكيات CNC، معمل قياس به جهاز CMM"}, "tracks": [{"en": "CAM Programming & 5-Axis", "ar": "برمجة CAM والتشغيل خماسي المحاور"}, {"en": "Precision Turning & Mill-Turn", "ar": "الخراطة الدقيقة والخراطة-التفريز"}, {"en": "Tool & Mold Making", "ar": "صناعة العدد والقوالب"}], "capstone": {"en": "Manufacture a functional multi-part assembly (e.g. a precision vise or gear pump housing) with turned, milled and threaded features and at least one H7/g6 fit: process plans, CAM and manual programs, setup and machining, FAI report, assembly and a cost and cycle-time analysis. 80 hours, 40% of the final examination.", "ar": "تصنيع مجموعة وظيفية متعددة الأجزاء (مثل منجلة دقيقة أو جسم مضخة تروس) بها أجزاء مخروطة ومفرزة ومقلوظة وازدواج H7/g6 واحد على الأقل: خطط العمليات، برامج CAM ويدوية، الإعداد والتشغيل، تقرير فحص القطعة الأولى، التجميع، وتحليل التكلفة وزمن الدورة. 80 ساعة، 40% من الامتحان النهائي."}, "duration": {"en": "3 years, 4,800 nominal hours", "ar": "3 سنوات، 4,800 ساعة اسمية"}, "pvtd": null, "adopts": null, "system_b": null, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb
 WHERE program_code = 'CNC';
UPDATE trades SET profile = '{"occupation": {"en": "Garment Production Technician", "ar": "فني إنتاج ملابس"}, "overview": {"en": "Prepares Garment Production Technicians to turn design concepts into high-quality, cost-efficient garments at industrial scale: textile science, pattern making and grading, cutting room, sewing technology, finishing, quality assurance and production engineering, up to 2D/3D CAD, automated cutting and digital printing. Benchmarked to the German occupations Modenäher/-in and Maßschneider/-in and international buyer expectations.", "ar": "يُعدّ البرنامج فنيي إنتاج الملابس لتحويل أفكار التصميم إلى ملابس عالية الجودة وفعالة التكلفة على نطاق صناعي: علوم النسيج، وعمل الباترون وتدريجه، وصالة القص، وتكنولوجيا الخياطة، والتشطيب، وضمان الجودة، والهندسة الإنتاجية، وصولًا إلى CAD ثنائي وثلاثي الأبعاد والقص الآلي والطباعة الرقمية. مرجعيته المهنتان الألمانيتان Modenäher/-in وMaßschneider/-in وتوقعات المشترين الدوليين."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Sample maker, pattern maker/grader, cutting master, line supervisor, QC inspector, industrial engineering assistant", "ar": "صانع عينات، صانع ومدرّج باترونات، رئيس قص، مشرف خط، مفتش جودة، مساعد هندسة صناعية"}, "standards": "ISO 3635 / 8559, ISO 4915 / 4916, AQL ISO 2859-1, OEKO-TEX, WRAP, amfori BSCI, Higg Index", "equipment": {"en": "Lockstitch, overlock, coverstitch, bartack, buttonhole and button-sew machines; spreading tables; straight-knife and band-knife cutters; fusing press; steam finishing; CAD pattern system (Gerber/Lectra/Optitex); 3D virtual fitting software", "ar": "ماكينات درزة، أوفرلوك، كفر ستيتش، بارتاك، عراوي وزراير؛ طاولات فرد؛ مقصات كهربائية سكين مستقيم وشريطي؛ مكبس لصق؛ تشطيب بالبخار؛ نظام باترون بالحاسوب؛ برمجيات القياس الافتراضي ثلاثي الأبعاد"}, "tracks": [{"en": "Pattern Engineering & 3D CAD", "ar": "هندسة الباترون وCAD ثلاثي الأبعاد"}, {"en": "Production & Industrial Engineering", "ar": "الإنتاج والهندسة الصناعية"}, {"en": "Quality & Compliance Management", "ar": "إدارة الجودة والامتثال"}], "capstone": {"en": "From tech pack to production-ready style: patterns (manual and CAD), a 3D virtual and a physical fit sample, marker and consumption, operation bulletin with SMVs and a balanced line, garment costing, a 12-piece mini-run across 3 sizes inspected to AQL 2.5 and a sustainability and compliance statement. 90 hours, 40% of the final examination.", "ar": "من ملف المواصفات إلى موديل جاهز للإنتاج: الباترونات (يدويًا وCAD)، عينة افتراضية ثلاثية الأبعاد وعينة قياس فعلية، الماركر والاستهلاك، نشرة العمليات بالدقائق القياسية وخط متوازن، تكلفة القطعة، تشغيلة مصغرة من 12 قطعة بثلاثة مقاسات تُفحص وفق AQL 2.5، وبيان الاستدامة والامتثال. 90 ساعة، 40% من الامتحان النهائي."}, "duration": {"en": "3 years, 4,800 nominal hours", "ar": "3 سنوات، 4,800 ساعة اسمية"}, "pvtd": null, "adopts": null, "system_b": null, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb
 WHERE program_code = 'RMG';
UPDATE trades SET profile = '{"occupation": {"en": "Industrial Mechatronics & Maintenance Technician", "ar": "فني ميكاترونكس وصيانة صناعية"}, "overview": {"en": "Prepares Industrial Mechatronics & Maintenance Technicians to install, align, commission, maintain and repair production equipment combining mechanical, hydraulic, pneumatic, electrical and control elements, with emphasis on rigging, precision alignment, fluid power, condition monitoring and reliability-centred maintenance. Benchmarked to the German occupations Industriemechaniker/-in and Mechatroniker/-in.", "ar": "يُعدّ البرنامج فنيي الميكاترونكس والصيانة الصناعية لتركيب ومحاذاة وتشغيل وصيانة وإصلاح معدات الإنتاج التي تجمع العناصر الميكانيكية والهيدروليكية والهوائية والكهربائية وعناصر التحكم، مع التركيز على الرفع والتركيب والمحاذاة الدقيقة وقدرة الموائع ومراقبة الحالة والصيانة المرتكزة على الاعتمادية. مرجعيته المهنتان الألمانيتان Industriemechaniker/-in وMechatroniker/-in."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Maintenance mechanic, mechatronics technician, installation/commissioning technician, condition-monitoring technician, maintenance planner (junior)", "ar": "ميكانيكي صيانة، فني ميكاترونكس، فني تركيب وتشغيل، فني مراقبة حالة، مخطط صيانة (مبتدئ)"}, "standards": "ISO 12100, ISO 4413, ISO 4414, ISO 1219, ISO 10816 / 20816, ISO 55000, EN 13306, LOLER", "equipment": {"en": "Pump and gearbox rigs, laser shaft-alignment system, hydraulic and electro-pneumatic trainers, mechatronic production line (MPS-type), vibration analyzer, thermal camera, ultrasonic detector, CMMS software, rigging and lifting kit", "ar": "منصات مضخات وصناديق تروس، جهاز ضبط استقامة بالليزر، وحدات تدريب هيدروليك وهواء مضغوط كهربي، خط إنتاج ميكاترونيك، محلل اهتزازات، كاميرا حرارية، كاشف بالموجات فوق الصوتية، برنامج إدارة صيانة، معدات رفع"}, "tracks": [{"en": "Predictive Maintenance & Reliability", "ar": "الصيانة التنبؤية والاعتمادية"}, {"en": "Mechatronics & Automated Lines", "ar": "الميكاترونكس والخطوط الآلية"}, {"en": "Equipment Installation & Commissioning", "ar": "تركيب المعدات وتشغيلها"}], "capstone": {"en": "Reliability improvement of a critical production asset in the host enterprise: CMMS history and MTBF/MTTR, condition monitoring (vibration, thermography, oil), FMEA and RCA, a corrective intervention under LOTO and permits, recommissioning, an improved PM/PdM plan and a cost-benefit presentation. 80 hours, 40% of the final examination.", "ar": "تحسين اعتمادية أصل إنتاجي حرج في المنشأة المضيفة: تحليل سجل CMMS وحساب MTBF/MTTR، مراقبة الحالة (اهتزاز، تصوير حراري، زيت)، تحليل FMEA والسبب الجذري، تدخل تصحيحي مع الإقفال والتصاريح، إعادة التشغيل، خطة صيانة وقائية وتنبؤية محسّنة، وعرض التكلفة والعائد. 80 ساعة، 40% من الامتحان النهائي."}, "duration": {"en": "3 years, 4,800 nominal hours", "ar": "3 سنوات، 4,800 ساعة اسمية"}, "pvtd": null, "adopts": null, "system_b": null, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb
 WHERE program_code = 'EIM';
UPDATE trades SET profile = '{"occupation": {"en": "Print Media Technologist", "ar": "فني تكنولوجيا الطباعة والوسائط"}, "overview": {"en": "Prepares Print Media Technologists to manage the complete print production chain: prepress and colour management, offset lithography, flexography and packaging, digital and wide-format, screen printing and post-press finishing. Modern print is data-driven: colour measurement, workflow automation and sustainable substrates and inks. Benchmarked to the German occupation Medientechnologe/-in Druck and ISO 12647.", "ar": "يُعدّ البرنامج فنيي تكنولوجيا الطباعة لإدارة سلسلة الإنتاج الطباعي كاملة: ما قبل الطباعة وإدارة الألوان، والأوفست، والفلكسوجراف والتغليف، والطباعة الرقمية وعريضة النسق، والشاشة الحريرية، وتشطيب ما بعد الطباعة. الطباعة الحديثة قائمة على البيانات: قياس اللون وأتمتة سير العمل والخامات والأحبار المستدامة. مرجعيته المهنة الألمانية Medientechnologe/-in Druck ومعايير ISO 12647."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Prepress operator, offset press operator, flexo printer, digital print technician, finishing operator, colour/quality technician, print production planner", "ar": "مشغل ما قبل الطباعة، مشغل ماكينة أوفست، طابع فلكسو، فني طباعة رقمية، مشغل تشطيب، فني لون وجودة، مخطط إنتاج طباعي"}, "standards": "ISO 12647-2 / -6 / -8, ISO 15930 (PDF/X), ISO 13655, G7, Fogra, EU 1935/2004, FSC", "equipment": {"en": "Mac/PC prepress lab with Adobe suite and preflight tools, CTP platesetter, 4-color sheetfed offset press, narrow-web flexo press, production digital press (toner and inkjet), wide-format printer, screen-printing station, guillotine, folder, saddle stitcher, die-cutter, laminator, spectrophotometer and densitometer", "ar": "معمل ما قبل الطبع ببرمجيات Adobe وأدوات الفحص المسبق، جهاز تصوير الألواح CTP، ماكينة أوفست 4 ألوان، ماكينة فلكسو ضيقة العرض، ماكينة طباعة رقمية إنتاجية، طابعة واسعة الحجم، محطة شاشة حريرية، مقصلة، ماكينة طي، ماكينة تدبيس، ماكينة تكسير، ماكينة سلوفان، مقياس طيفي ومقياس كثافة"}, "tracks": [{"en": "Packaging & Flexo Printing", "ar": "التغليف وطباعة الفلكسو"}, {"en": "Digital & Wide-Format Production", "ar": "الإنتاج الرقمي وعريض النسق"}, {"en": "Prepress & Colour Management", "ar": "ما قبل الطباعة وإدارة الألوان"}], "capstone": {"en": "End-to-end production of a branded packaging and print campaign: a folding carton or label with dieline, barcode and brand spot colour; a bilingual (Arabic/English) brochure; and a variable-data or wide-format piece, with preflight reports, contract proofs, ISO 12647 QC data, a cost estimate and a sustainability statement. 80 hours, 40% of the final examination.", "ar": "إنتاج متكامل لحملة تغليف وطباعة لعلامة تجارية: علبة كرتونية أو ملصق بخط قالب وباركود ولون خاص للعلامة؛ وكتيب ثنائي اللغة (عربي/إنجليزي)؛ وقطعة بيانات متغيرة أو عريضة النسق، مع تقارير الفحص المسبق والبروفات التعاقدية وبيانات الجودة وفق ISO 12647 وتقدير التكلفة وبيان الاستدامة. 80 ساعة، 40% من الامتحان النهائي."}, "duration": {"en": "3 years, 4,800 nominal hours", "ar": "3 سنوات، 4,800 ساعة اسمية"}, "pvtd": null, "adopts": null, "system_b": null, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb
 WHERE program_code = 'PRT';
UPDATE trades SET profile = '{"occupation": {"en": "Applied AI & Data Technician", "ar": "فني ذكاء اصطناعي وبيانات تطبيقي"}, "overview": {"en": "Prepares Applied AI & Data Technicians who bridge the shop floor and the data layer: collecting and preparing industrial data, deploying sensors and edge devices, integrating ready-made AI tools (vision inspection, predictive maintenance, generative AI assistants), monitoring models and applying AI responsibly and safely. Aligned with Fachinformatiker/-in für Daten- und Prozessanalyse and the OECD, UNESCO and ISO/IEC 42001 frameworks.", "ar": "يُعدّ البرنامج فنيي الذكاء الاصطناعي والبيانات التطبيقيين الذين يربطون أرض المصنع بطبقة البيانات: جمع البيانات الصناعية وتجهيزها، ونشر الحساسات وأجهزة الحافة، ودمج أدوات الذكاء الاصطناعي الجاهزة (الفحص بالرؤية، الصيانة التنبؤية، المساعدات التوليدية)، ومراقبة النماذج، وتطبيق الذكاء الاصطناعي بمسؤولية وأمان. يتوافق مع مهنة Fachinformatiker/-in für Daten- und Prozessanalyse وأطر OECD وUNESCO وISO/IEC 42001."}, "eqf": "EQF 4–5", "hours": 4800, "occupations": {"en": "AI/data technician, industrial IoT technician, vision-inspection technician, AI tools integrator, data annotation lead, MLOps support technician, AI-enabled maintenance technician", "ar": "فني ذكاء اصطناعي وبيانات، فني إنترنت أشياء صناعي، فني فحص بالرؤية، مُدمج أدوات ذكاء اصطناعي، قائد وسم بيانات، فني دعم MLOps، فني صيانة مدعوم بالذكاء الاصطناعي"}, "standards": "ISO/IEC 22989, ISO/IEC 42001, ISO/IEC 23894, ISO/IEC 27001, IEC 62443, OECD & UNESCO AI principles", "equipment": {"en": "GPU-enabled lab workstations, Python/Jupyter environment, edge AI kits (e.g., Jetson/Raspberry Pi + accelerators), industrial cameras and lighting, IoT sensor kits, PLC with OPC UA, cloud sandbox accounts, enterprise generative-AI assistant licenses, data-labeling platform", "ar": "محطات عمل مزودة بمعالجات رسومية، بيئة Python/Jupyter، أطقم ذكاء اصطناعي طرفية، كاميرات صناعية وإضاءة، أطقم حساسات إنترنت الأشياء، PLC بواجهة OPC UA، حسابات سحابية تجريبية، تراخيص مساعدات ذكاء اصطناعي توليدي، منصة توسيم بيانات"}, "tracks": [{"en": "AI for Smart Manufacturing & Maintenance", "ar": "الذكاء الاصطناعي للتصنيع والصيانة الذكية"}, {"en": "Computer Vision & Quality Inspection", "ar": "الرؤية الحاسوبية وفحص الجودة"}, {"en": "Generative AI & Workflow Automation for Enterprises", "ar": "الذكاء الاصطناعي التوليدي وأتمتة سير العمل للمنشآت"}], "capstone": {"en": "Deploy a responsible AI solution for a real vocational problem (e.g. vision inspection of CNC parts or predictive maintenance of an EIM asset): problem and metrics, documented data, a deployed solution, an AI risk and impact assessment and model card, two weeks in production with monitoring, user training and a value presentation. 100 hours, 40% of the final examination.", "ar": "نشر حل ذكاء اصطناعي مسؤول لمشكلة مهنية حقيقية (مثل الفحص بالرؤية لقطع CNC أو الصيانة التنبؤية لأصل في برنامج الصيانة): تحديد المشكلة والمقاييس، بيانات موثقة، حل منشور، تقييم مخاطر وأثر وبطاقة نموذج، أسبوعان في التشغيل الفعلي مع المراقبة، تدريب المستخدمين، وعرض القيمة المحققة. 100 ساعة، 40% من الامتحان النهائي."}, "duration": {"en": "3 years, 4,800 nominal hours (institute share 45/35/25% due to lab intensity)", "ar": "3 سنوات، 4,800 ساعة اسمية (نسبة المعهد 45/35/25% لكثافة العمل المعملي)"}, "pvtd": null, "adopts": null, "system_b": null, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb
 WHERE program_code = 'AIT';
UPDATE trades SET profile = '{"occupation": {"en": "Workplace Coordination & Business Support Technician", "ar": "فني تنسيق العمل ودعم الأعمال"}, "overview": {"en": "The transversal spine of every WABYS specialisation: communication, problem solving, teamwork, self-management, digital fluency and professional conduct, in a structured, assessed three-year progression. Integrated mode (mandatory): 120 institute hours a year inside every technical programme plus workplace evidence in the logbook. Standalone mode (optional): a full three-year programme for roles such as production coordinator, technical customer service, team leader and training assistant.", "ar": "العمود الفقري المشترك لكل تخصصات وابيز: التواصل، وحل المشكلات، والعمل الجماعي، وإدارة الذات، والطلاقة الرقمية، والسلوك المهني، في تدرج منظم ومُقيَّم على ثلاث سنوات. النمط المدمج (إلزامي): 120 ساعة سنويًا داخل كل برنامج فني مع أدلة تطبيق في سجل التدريب. النمط المستقل (اختياري): برنامج كامل لثلاث سنوات لأدوار مثل منسق الإنتاج وخدمة العملاء الفنية وقائد الفريق ومساعد التدريب."}, "eqf": "EQF 4", "hours": 360, "occupations": {"en": "Employability, team leadership readiness, entrepreneurial capability, lifelong learning", "ar": "قابلية التوظيف، الجاهزية لقيادة الفريق، القدرة الريادية، التعلم مدى الحياة"}, "standards": "OECD Learning Compass 2030, WEF Future of Jobs, EU DigComp 2.2, EntreComp, Handlungskompetenz", "equipment": {"en": "Training rooms, digital productivity tools, logbook, team project boards", "ar": "قاعات تدريب، أدوات إنتاجية رقمية، سجل التدريب، لوحات المشروعات الجماعية"}, "tracks": [], "capstone": {"en": "Professional leadership portfolio and improvement pitch, integrated with the learner''s technical capstone: documented leadership evidence, a bilingual professional portfolio, a 10-minute data-backed improvement pitch to an industry panel and a structured mock interview. 20% of the host programme''s final examination.", "ar": "ملف القيادة المهنية وعرض التحسين، مدمج مع مشروع التخرج الفني للمتدرب: أدلة موثقة على القيادة، ملف أعمال مهني ثنائي اللغة، عرض تحسين مدعوم بالبيانات مدته 10 دقائق أمام لجنة من الصناعة، ومقابلة تجريبية منظمة. 20% من الامتحان النهائي للبرنامج المضيف."}, "duration": {"en": "Integrated: 360 institute hours over 3 years + workplace evidence · Standalone: 4,800 hours", "ar": "المدمج: 360 ساعة على 3 سنوات + أدلة من موقع العمل · المستقل: 4,800 ساعة"}, "pvtd": null, "adopts": null, "system_b": null, "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb
 WHERE program_code = 'CWS';
UPDATE competencies c SET title = 'Plan and track a team project', title_ar = 'تخطيط مشروع جماعي ومتابعته'
  FROM competency_frameworks f WHERE f.id = c.framework_id AND f.code = 'WABYS-CWS-2026' AND c.code = 'CWS-Y2-S-03';
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('iel', 'IEL', 'Industrial Electronics', 'الإلكترونيات الصناعية', 'M7 3v4M12 3v4M17 3v4M7 17v4M12 17v4M17 17v4M3 7h18v10H3zM8 12h8', 90, 'IEL', '#f08c00',
  '{"occupation": {"en": "Industrial Electronics Technician", "ar": "فني إلكترونيات صناعية"}, "overview": {"en": "The Industrial Electronics program prepares Industrial Electronics Technicians (فني إلكترونيات صناعية) to build, test, install, program, and repair the electronic circuits, power stages, sensors, controllers, and embedded systems that run modern production equipment, utilities, and smart products. Demand comes from factory automation, electronics assembly plants, water and energy utilities, medical and laboratory equipment service, and the growing local manufacture of control boards. The program combines the full PVTD electronics sequence (analog, digital, optoelectronics, power electronics, PLC, PCB, sensors, hydraulics/pneumatics, microprocessors, estimating) with WABYS additions: embedded programming, industrial communication, IIoT, and standards-based workmanship.", "ar": "يُعد برنامج الإلكترونيات الصناعية فنيي الإلكترونيات الصناعية لبناء الدوائر الإلكترونية ومراحل القدرة والحساسات والمتحكمات والأنظمة المدمجة التي تشغّل معدات الإنتاج والمرافق والمنتجات الذكية، واختبارها وتركيبها وبرمجتها وإصلاحها. ويأتي الطلب من أتمتة المصانع ومصانع تجميع الإلكترونيات ومرافق المياه والطاقة وصيانة الأجهزة الطبية والمعملية والتصنيع المحلي المتنامي للوحات التحكم. ويجمع البرنامج تسلسل الإلكترونيات الكامل لدى مصلحة الكفاية الإنتاجية (التناظرية، الرقمية، الضوئية، القوى، PLC، الدوائر المطبوعة، الحساسات، الهيدروليك والنيوماتيك، المعالجات الدقيقة، المقايسات) مع إضافات وابيز: البرمجة المدمجة والاتصالات الصناعية وإنترنت الأشياء الصناعي والصنعة القائمة على المعايير."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Industrial electronics technician, control-panel and PCB assembly technician, instrumentation technician (junior), electronic repair technician, embedded/IoT technician", "ar": "فني إلكترونيات صناعية، فني تجميع لوحات تحكم ودوائر مطبوعة، فني أجهزة قياس مبتدئ، فني إصلاح إلكترونيات، فني أنظمة مدمجة"}, "standards": "IEC 60617 (symbols), IEC 61010-1 (lab equipment safety), IEC 61340-5-1 (ESD), IPC-2221 (PCB design), IPC-A-610 (assembly acceptability), IEC 61131-3 (PLC), IEC 60747 (semiconductors), ISO 1219 (fluid-power symbols)", "equipment": {"en": "Electronics benches (2-channel oscilloscopes, generators, supplies, LCR), digital and analog trainers, power-electronics trainer, PLC trainers, PCB CAD (e.g., KiCad), UV exposure and etching line or PCB mill, SMD rework stations, sensor & process-control trainer, electro-pneumatic/hydraulic trainers, microcontroller kits", "ar": "طاولات إلكترونيات، وحدات تدريب رقمية وتناظرية، وحدة إلكترونيات قوى، وحدات PLC، برنامج تصميم دوائر مطبوعة، خط تعريض وحفر، محطات لحام SMD، وحدة حساسات وتحكم، وحدات هيدروليك ونيوماتيك، أطقم متحكمات دقيقة"}, "tracks": [{"en": "Industrial Automation & Instrumentation", "ar": "الأتمتة الصناعية والأجهزة الدقيقة"}, {"en": "Embedded Systems & IoT", "ar": "الأنظمة المدمجة وإنترنت الأشياء"}, {"en": "Power Electronics & Drives", "ar": "إلكترونيات القوى والمحركات"}], "capstone": {"en": "IEL Capstone: \"Design, Build and Commission an Automated Measurement & Control Unit\". From a customer brief (e.g., tank level, oven temperature or conveyor sorting), the learner (1) selects sensors and designs signal conditioning; (2) designs and fabricates a PCB for the control or interface stage; (3) programs a microcontroller or PLC including a PID or sequence function; (4) builds the power stage with correct protection; (5) prepares the estimate (مقايسة) and documentation pack; (6) commissions, demonstrates and defends the project in a 30-minute technical interview. Duration: 80 hours (System A) / 192 hours centre time (System B). Weighting: 40% of the final examination.", "ar": "مشروع التخرج: تصميم وبناء وتشغيل وحدة قياس وتحكم مؤتمتة. انطلاقًا من طلب عميل (مثل منسوب خزان أو حرارة فرن أو فرز على سير ناقل) يقوم المتدرب بما يلي: (1) يختار الحساسات ويصمم دوائر تهيئة الإشارة؛ (2) يصمم ويصنع لوحة دوائر مطبوعة لمرحلة التحكم أو الواجهة؛ (3) يبرمج متحكمًا دقيقًا أو PLC بما في ذلك وظيفة PID أو تسلسل؛ (4) يبني مرحلة القدرة بالحماية الصحيحة؛ (5) يعد المقايسة وملف التوثيق؛ (6) يشغّل المشروع ويعرضه ويدافع عنه في مقابلة فنية مدتها 30 دقيقة. المدة: 80 ساعة (النظام أ) / 192 ساعة بالمركز (النظام ب). الوزن: 40٪ من الامتحان النهائي."}, "duration": {"en": "System A: 3 years, 4,800 nominal hours · System B: 3 years, 2,304 centre hours (576 / 864 / 864) + enterprise days", "ar": "النظام (أ): 3 سنوات، 4800 ساعة اسمية · النظام (ب): 3 سنوات، 2304 ساعة بالمركز + أيام المنشأة"}, "pvtd": "الإلكترونيات الصناعية", "adopts": {"en": "ETF-Y1 (all), CPM-01 , CPM-02 , CPM-03 , CPM-04", "ar": "الأساس الكهروتقني كاملًا والوحدات المشتركة 01–04"}, "system_b": [["Year", "Sem.", "#", "Training Unit", "الوحدة التدريبية", "Mapped codes", "Hours"], ["Y1", "1", "1", "Occupational Safety & Health (electricity)", "السلامة والصحة المهنية – كهرباء", "ETF-K-01, S-01", "32"], ["Y1", "1", "2", "Electricity Fundamentals", "أسس الكهرباء", "ETF-K-02, K-03, K-06, S-02, S-03", "112"], ["Y1", "1", "3", "Electronics Fundamentals", "أسس الإلكترونيات", "ETF-K-04, K-05, S-04…S-07", "112"], ["Y1", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y1", "2", "4", "Basic Electronic Circuits", "دوائر الإلكترونيات الأساسية", "IEL-Y1-K-01 , K-03, S-01, S-02, S-05", "112"], ["Y1", "2", "5", "Analog Electronics", "الإلكترونيات التماثلية", "IEL-Y1-K-02 , S-03, S-04", "112"], ["Y1", "2", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["", "", "", "Year 1", "", "", "576"], ["Y2", "1", "6", "Digital Electronics (incl. arithmetic annex)", "الإلكترونيات الرقمية", "IEL-Y2-K-01 , S-01", "144"], ["Y2", "1", "7", "Optoelectronics", "الإلكترونيات الضوئية", "K-02, S-02", "72"], ["Y2", "1", "8", "Power Electronics", "إلكترونيات القوى", "K-03, S-03", "120"], ["Y2", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y2", "2", "9", "PLC", "المتحكمات المنطقية المبرمجة", "K-04, S-04", "144"], ["Y2", "2", "10", "Electronic Circuit Drawing & PCB Fabrication", "رسم الدوائر وتصنيع الدوائر المطبوعة", "K-05, K-07, S-05", "144"], ["Y2", "2", "11", "Electronic Fault-Finding & Maintenance", "تتبع الأعطال والصيانة", "K-06, S-06", "144"], ["Y2", "2", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["", "", "", "Year 2", "", "", "864"], ["Y3", "1", "12", "Physical-Quantity Measurement & Sensors", "أجهزة قياس الكميات الفيزيائية", "IEL-Y3-K-01 , S-01", "144"], ["Y3", "1", "13", "Hydraulic & Pneumatic Circuits (complementary skills)", "دوائر الهيدروليك والنيوماتيك (المهارات التكميلية)", "K-03, S-03", "120"], ["Y3", "1", "14", "Microprocessors & Microcontrollers", "المعالجات والمتحكمات الدقيقة", "K-02, S-02", "120"], ["Y3", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y3", "2", "15", "Drives, Industrial Communication & IIoT", "المحركات والاتصالات الصناعية", "K-04, K-05, S-04, S-05", "144"], ["Y3", "2", "16", "Estimating & Costing", "المقايسات", "K-06, K-07, S-06", "48"], ["Y3", "2", "17", "Capstone Project", "مشروع التخرج", "All Y3", "192"], ["Y3", "2", "—", "Review & Test / Final Trade Test", "مراجعة واختبار / اختبار المهنة النهائي", "", "48"], ["", "", "", "Year 3", "", "", "864"]], "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('csn', 'CSN', 'Computer Systems & Networks', 'تشغيل وصيانة أنظمة وشبكات الحاسوب', 'M4 4h16v6H4zM4 14h16v6H4zM8 7h.01M8 17h.01M12 10v4', 100, 'CSN', '#1098ad',
  '{"occupation": {"en": "IT Support & Network Technician", "ar": "فني دعم تقني وشبكات"}, "overview": {"en": "The Computer Systems & Networks program prepares IT Support & Network Technicians (فني دعم تقني وشبكات) to assemble, install, secure, maintain, and repair computers, servers, and network infrastructure for enterprises, schools, hospitals, and public services. Every digitized workplace needs technicians who can keep end-user devices, local networks, broadband links, and core services running safely. The program keeps PVTD''s strong hardware and networking practice and modernizes it: current client and server operating systems, IPv6, fibre and Wi-Fi 6 access, secure remote management (SSH, not Telnet), virtualization, cloud services, scripting, and cybersecurity.", "ar": "يُعد برنامج أنظمة وشبكات الحاسوب فنيي الدعم التقني والشبكات لتجميع الحواسيب والخوادم والبنية الشبكية وتثبيتها وتأمينها وصيانتها وإصلاحها في المنشآت والمدارس والمستشفيات والخدمات العامة. ويحتفظ البرنامج بقوة التدريب العملي لدى مصلحة الكفاية الإنتاجية على العتاد والشبكات، ويحدّثه: أنظمة تشغيل حديثة للعملاء والخوادم، وIPv6، والألياف الضوئية وWi-Fi 6، والإدارة الآمنة عن بعد (SSH بدلًا من Telnet)، والمحاكاة الافتراضية، والخدمات السحابية، والبرمجة النصية، والأمن السيبراني."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "IT support technician, help-desk technician, network installation technician, junior system administrator, junior SOC/security technician", "ar": "فني دعم تقني، فني مكتب مساعدة، فني تركيب شبكات، مدير أنظمة مبتدئ، فني أمن معلومات مبتدئ"}, "standards": "ANSI/TIA-568 and ISO/IEC 11801 (cabling), IEEE 802.3 / 802.11, ITIL 4 Foundation concepts, ISO/IEC 27001 awareness, Egyptian Personal Data Protection Law No. 151/2020; vendor-neutral benchmarks equivalent to CompTIA A+ / Network+ and CCNA-level objectives", "equipment": {"en": "PC assembly benches with spare-parts pool, ESD stations, cabling and fibre-termination kits with certifier, managed switches and routers (rack per 4 learners), wireless APs and controllers, server hardware and hypervisor host, firewall appliance, simulation software (Packet Tracer/GNS3), virtualization platform", "ar": "طاولات تجميع حواسيب، محطات ESD، أطقم كابلات وألياف وجهاز شهادة، محولات وموجهات مُدارة، نقاط وصول لاسلكية، خادم ومضيف افتراضي، جدار حماية، برامج محاكاة"}, "tracks": [{"en": "Network Infrastructure", "ar": "البنية التحتية للشبكات"}, {"en": "Systems & Cloud Administration", "ar": "إدارة الأنظمة والسحابة"}, {"en": "Cybersecurity Operations (junior)", "ar": "عمليات الأمن السيبراني"}], "capstone": {"en": "CSN Capstone: \"Design, Deploy and Secure the IT Infrastructure of a Small Enterprise\". For a real or simulated client (20–50 users), the learner (1) surveys requirements; (2) designs the network, IP plan and security zones; (3) installs and certifies cabling and wireless; (4) configures switching, routing, firewall and VPN; (5) deploys directory, file and backup services (on-premises or cloud); (6) hands over documentation and trains users; (7) defends the project in a 30-minute technical interview. Duration: 80 h (System A) / 192 h (System B). Weighting: 40% of the final examination.", "ar": "مشروع التخرج: تصميم ونشر وتأمين البنية التقنية لمنشأة صغيرة. لعميل حقيقي أو افتراضي (20–50 مستخدمًا) يقوم المتدرب بما يلي: (1) يحصر المتطلبات؛ (2) يصمم الشبكة وخطة العناوين ومناطق الأمان؛ (3) يركب الكابلات والشبكة اللاسلكية ويعتمدها بالاختبار؛ (4) يهيئ التحويل والتوجيه والجدار الناري وVPN؛ (5) ينشر خدمات الدليل والملفات والنسخ الاحتياطي (محليًا أو سحابيًا)؛ (6) يسلم التوثيق ويدرب المستخدمين؛ (7) يدافع عن المشروع في مقابلة فنية مدتها 30 دقيقة. المدة: 80 ساعة (النظام أ) / 192 ساعة (النظام ب). الوزن: 40٪ من الامتحان النهائي."}, "duration": {"en": "System A: 3 years, 4,800 nominal hours · System B: 2,304 centre hours (576 / 864 / 864) + enterprise days", "ar": "النظام (أ): 4800 ساعة · النظام (ب): 2304 ساعة بالمركز + أيام المنشأة"}, "pvtd": "صيانة وتشغيل أنظمة وشبكات الحاسوب", "adopts": {"en": "ETF-Y1 (all), CPM-04 ; CPM-01 integrated as CSN-Y1-K-04", "ar": "الأساس الكهروتقني كاملًا، مراقبة الجودة؛ مبادئ الحاسب مدمجة"}, "system_b": [["Year", "Sem.", "#", "Training Unit", "الوحدة التدريبية", "Mapped codes", "Hours"], ["Y1", "1", "1", "Occupational Safety & Health", "السلامة والصحة المهنية", "ETF-K-01, S-01", "32"], ["Y1", "1", "2", "Electricity Fundamentals", "أسس الكهرباء", "ETF-K-02, K-03, K-06, S-02, S-03", "112"], ["Y1", "1", "3", "Electronics Fundamentals", "أسس الإلكترونيات", "ETF-K-04, K-05, S-04…S-07", "112"], ["Y1", "1", "—", "Review & Test", "مراجعة واختبار", "", "32"], ["Y1", "2", "4", "Installing & Assembling Computer Components", "تثبيت وتجميع مكونات أجهزة الحاسوب", "CSN-Y1-K-01 , S-01, S-02", "160"], ["Y1", "2", "5", "Installing & Configuring Operating Systems", "تنصيب وإعداد أنظمة تشغيل الحاسوب", "K-02, K-03, S-03, S-04", "96"], ["Y1", "2", "—", "Review & Test", "مراجعة واختبار", "", "32"], ["", "", "", "Year 1", "", "", "576"], ["Y2", "1", "6", "Diagnosing & Repairing Computer Faults", "تشخيص وإصلاح أعطال أنظمة الحاسوب", "CSN-Y2-K-01 , S-01", "144"], ["Y2", "1", "7", "Network Infrastructure", "تنصيب البنية الأساسية لشبكات الحاسوب", "K-02, S-02", "72"], ["Y2", "1", "8", "Configuring Network Devices", "استخدام وضبط إعدادات أجهزة الشبكة", "K-03, S-03", "144"], ["Y2", "1", "9", "Network Drawing & Simulation", "رسم ومحاكاة شبكات الحاسوب", "K-04, S-04", "72"], ["Y2", "2", "10", "Server Installation & Administration", "تنصيب وإعداد نظام تشغيل الخادم", "K-05, S-05", "168"], ["Y2", "2", "11", "Broadband (DSL/FTTH) & Wireless Networks", "خطوط الاشتراك الرقمي والشبكات اللاسلكية", "K-06, S-06", "144"], ["Y2", "1–2", "—", "Review & Test (2 × 60 h)", "مراجعة واختبار", "", "120"], ["", "", "", "Year 2", "", "", "864"], ["Y3", "1", "12", "Network Security", "أمن الشبكات", "CSN-Y3-K-01 , S-01", "144"], ["Y3", "1", "13", "Virtualization, Cloud & Scripting", "المحاكاة الافتراضية والسحابة والبرمجة النصية", "K-02, K-03, S-02, S-03", "192"], ["Y3", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y3", "2", "14", "Service Desk, VoIP, CCTV & Data Room", "مكتب الخدمة والهاتف الشبكي والمراقبة وغرف الخوادم", "K-04, K-05, K-06, K-07, S-04, S-05, S-07", "192"], ["Y3", "2", "15", "Capstone Project", "مشروع التخرج", "All Y3", "240"], ["Y3", "2", "—", "Review & Test / Final Trade Test", "مراجعة واختبار / اختبار المهنة النهائي", "", "48"], ["", "", "", "Year 3", "", "", "864"]], "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('rac', 'RAC', 'Refrigeration & Air-Conditioning', 'التبريد وتكييف الهواء', 'M12 2v20M4.9 4.9l14.2 14.2M2 12h20M4.9 19.1 19.1 4.9M9 3l3 3 3-3M9 21l3-3 3 3', 110, 'RAC', '#4dabf7',
  '{"occupation": {"en": "RAC Technician", "ar": "فني تبريد وتكييف"}, "overview": {"en": "The Refrigeration & Air-Conditioning program prepares RAC Technicians (فني تبريد وتكييف) to install, commission, maintain, and repair domestic, commercial, and light-industrial refrigeration and air-conditioning systems, including their electrical controls. In a hot climate with fast-growing housing, retail cold chains, food processing, and data centres, RAC technicians are among the most demanded trades. The program carries PVTD''s refrigeration-circuit and control-drawing content and updates it to current practice: low-GWP and flammable refrigerants (R600a, R290, R32), safe recovery and handling under the Montreal Protocol and Kigali Amendment, inverter compressors, VRF systems, and energy-efficiency labelling.", "ar": "يُعد برنامج التبريد وتكييف الهواء فنيي التبريد والتكييف لتركيب أنظمة التبريد والتكييف المنزلية والتجارية والصناعية الخفيفة ودوائر التحكم الكهربي فيها وتشغيلها وصيانتها وإصلاحها. ويُعد فني التبريد من أكثر المهن طلبًا في مناخ حار يشهد توسعًا في الإسكان وسلاسل التبريد التجارية وتصنيع الأغذية ومراكز البيانات. ويحمل البرنامج محتوى دوائر التبريد ورسم دوائر التحكم لدى مصلحة الكفاية الإنتاجية، ويحدّثه وفق الممارسات الحالية: وسائط التبريد منخفضة الاحترار والقابلة للاشتعال (R600a وR290 وR32)، والاسترجاع والتداول الآمن وفق بروتوكول مونتريال وتعديل كيغالي، والضواغط العاكسة (الإنفرتر)، وأنظمة VRF، وبطاقات كفاءة الطاقة."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Domestic and commercial refrigeration technician, split/central AC installer, chiller and AHU maintenance technician, cold-room technician, VRF service technician (junior)", "ar": "فني تبريد منزلي وتجاري، مركّب تكييف سبليت ومركزي، فني صيانة مبردات مياه ووحدات مناولة هواء، فني غرف تبريد"}, "standards": "ISO 5149 / EN 378 (refrigerating systems safety), ISO 817 / ASHRAE 34 (refrigerant designation and safety class), IEC 60335-2-24 (refrigerators), IEC 60335-2-40 (heat pumps and AC), IEC 60335-2-89 (commercial refrigeration), Montreal Protocol & Kigali Amendment, national energy-efficiency labelling", "equipment": {"en": "Tubing and brazing stations with nitrogen purge, recovery machines and cylinders, vacuum pumps with micron gauges, digital manifolds, electronic leak detectors (incl. HC-rated), charging scales, domestic and commercial refrigeration trainers, split/inverter AC rigs, cold-room mock-up, chiller/AHU demonstrator, control-panel benches", "ar": "محطات تشكيل ولحام بالنيتروجين، أجهزة استرجاع، مضخات تفريغ بمقياس ميكرون، مانيفولد رقمي، كاشف تسريب، ميزان شحن، وحدات تدريب منزلية وتجارية، مكيفات إنفرتر، نموذج غرفة تبريد، نموذج مبرد مياه"}, "tracks": [{"en": "Domestic & Commercial Refrigeration", "ar": "التبريد المنزلي والتجاري"}, {"en": "Central AC & Chillers", "ar": "التكييف المركزي ومبردات المياه"}, {"en": "VRF & Smart Controls", "ar": "أنظمة VRF والتحكم الذكي"}], "capstone": {"en": "RAC Capstone: \"Install, Commission and Hand Over a Refrigeration or AC System Using a Low-GWP Refrigerant\". The learner (1) calculates the load and selects equipment; (2) draws the refrigeration and electrical control circuits; (3) installs piping, brazes with nitrogen, pressure-tests and evacuates; (4) wires and commissions controls; (5) charges by weight and records performance (superheat, subcooling, currents, EER); (6) prepares the estimate and hand-over pack; (7) defends the project. Duration: 80 h (System A) / 216 h (System B). Weighting: 40% of the final examination.", "ar": "مشروع التخرج: تركيب وتشغيل وتسليم نظام تبريد أو تكييف بوسيط منخفض الاحترار. يقوم المتدرب بما يلي: (1) يحسب الحمل ويختار المعدات؛ (2) يرسم دائرة التبريد ودائرة التحكم الكهربائي؛ (3) يركب المواسير ويلحم بالمونة مع النيتروجين ويختبر الضغط ويفرّغ؛ (4) يوصل دوائر التحكم ويشغلها؛ (5) يشحن بالوزن ويسجل الأداء (التحميص الزائد والتبريد الزائد والتيارات ومعامل كفاءة الطاقة)؛ (6) يعد المقايسة وملف التسليم؛ (7) يدافع عن المشروع. المدة: 80 ساعة (النظام أ) / 216 ساعة (النظام ب). الوزن: 40٪ من الامتحان النهائي."}, "duration": {"en": "System A: 4,800 nominal hours · System B: 2,304 centre hours (576 / 864 / 864) + enterprise days", "ar": "النظام (أ): 4800 ساعة · النظام (ب): 2304 ساعة بالمركز"}, "pvtd": "صيانة وإصلاح أجهزة التبريد وتكييف الهواء", "adopts": {"en": "ETF-Y1 (K-01, K-02, K-03, K-06 full; K-04, K-05 at awareness level), CPM-01 , CPM-02 , CPM-03 , CPM-04", "ar": "الأساس الكهروتقني، والوحدات المشتركة 01–04"}, "system_b": [["Year", "Sem.", "#", "Training Unit", "الوحدة التدريبية", "Mapped codes", "Hours"], ["Y1", "1", "1", "Occupational Safety & Health", "السلامة والصحة المهنية", "ETF-K-01, S-01", "32"], ["Y1", "1", "2", "Electricity Fundamentals", "أسس الكهرباء", "ETF-K-02, K-03, K-06, S-02, S-03", "112"], ["Y1", "1", "3", "Mechanical Bench Work & Tubing", "التشغيل الميكانيكي وتشكيل المواسير", "CPM-02 , RAC-Y1-K-04 , S-01", "96"], ["Y1", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y1", "2", "4", "Refrigeration Circuits & Systems (PVTD Unit 4)", "دوائر وأنظمة التبريد", "RAC-Y1-K-01 , K-02, S-02, S-03, S-05", "120"], ["Y1", "2", "5", "Electrical Workshop Basics", "أساسيات ورشة الكهرباء", "CPM-03", "80"], ["Y1", "2", "6", "Refrigerants & Safe Handling", "وسائط التبريد والتداول الآمن", "K-03, S-04", "40"], ["Y1", "2", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["", "", "", "Year 1", "", "", "576"], ["Y2", "1", "7", "Refrigerator Electrics & Controls", "كهرباء ودوائر تحكم الثلاجات", "RAC-Y2-K-01 , S-01", "144"], ["Y2", "1", "8", "Measurement & Diagnosis", "القياس والتشخيص", "K-06, S-03", "72"], ["Y2", "1", "9", "AC Fundamentals & Psychrometrics", "أساسيات التكييف", "K-02, S-05", "72"], ["Y2", "1", "10", "Commercial Refrigeration", "التبريد التجاري", "K-04, S-06", "96"], ["Y2", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y2", "2", "11", "Split & Packaged Air-Conditioners", "مكيفات السبليت والوحدات المجمعة", "K-03, S-02", "216"], ["Y2", "2", "12", "RAC Electrical Control Circuits I", "دوائر التحكم الكهربي 1", "K-05, S-04", "168"], ["Y2", "2", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["", "", "", "Year 2", "", "", "864"], ["Y3", "1", "13", "Central AC, Chillers & VRF", "التكييف المركزي والمبردات وVRF", "RAC-Y3-K-01 , S-02", "216"], ["Y3", "1", "14", "Electrical Circuit Drawing & Controls for RAC II", "رسم دوائر التحكم الكهربي للتبريد والتكييف 2", "K-02, S-01", "168"], ["Y3", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y3", "2", "15", "BMS Controls & Energy Efficiency", "التحكم وإدارة المباني وكفاءة الطاقة", "K-03, K-04, K-05, S-03, S-04", "120"], ["Y3", "2", "16", "Estimating & Service Business", "المقايسات وأعمال الخدمة", "K-06, K-07, S-06", "48"], ["Y3", "2", "17", "Capstone Project", "مشروع التخرج", "All Y3", "216"], ["Y3", "2", "—", "Review & Test / Final Trade Test", "مراجعة واختبار / اختبار المهنة النهائي", "", "48"], ["", "", "", "Year 3", "", "", "864"]], "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('ham', 'HAM', 'Home Appliances Maintenance', 'صيانة الأجهزة المنزلية', 'M5 2h14v20H5zM5 7h14M12 15m-4 0a4 4 0 1 0 8 0 4 4 0 1 0-8 0M8 4.5h.01M11 4.5h.01', 120, 'HAM', '#e64980',
  '{"occupation": {"en": "Home Appliance Service Technician", "ar": "فني صيانة أجهزة منزلية"}, "overview": {"en": "The Home Appliances Maintenance program prepares Home Appliance Service Technicians (فني صيانة أجهزة منزلية) to diagnose, repair, safety-test, and install household electrical appliances, from heating and motor-driven small appliances to washing machines, refrigerators, microwave ovens, induction hobs, and connected \"smart\" appliances. Egypt''s large installed base of appliances, the growth of local appliance manufacturing, and manufacturer after-sales networks create steady demand for qualified technicians, and for self-employed service businesses. The program follows the PVTD occupation structure (common electrical/electronics first year, mechanical and electrical workshop basics, appliance motors) and adds full appliance families, electronic control boards, IEC 60335 safety testing, and customer-service and business skills.", "ar": "يُعد برنامج صيانة الأجهزة المنزلية فنيي صيانة الأجهزة المنزلية لتشخيص الأجهزة الكهربائية المنزلية وإصلاحها واختبار سلامتها وتركيبها، بدءًا من أجهزة التسخين والأجهزة الصغيرة ذات المحركات وحتى الغسالات والثلاجات وأفران الميكروويف والمواقد الحثية والأجهزة الذكية المتصلة. ويتبع البرنامج هيكل المهنة لدى مصلحة الكفاية الإنتاجية (سنة أولى مشتركة في الكهرباء والإلكترونيات، وأساسيات الورش الميكانيكية والكهربية، ومحركات الأجهزة)، ويضيف عائلات الأجهزة كاملة ولوحات التحكم الإلكترونية واختبارات السلامة وفق IEC 60335 ومهارات خدمة العملاء وإدارة الأعمال."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Appliance service technician (manufacturer after-sales or independent), field service technician, workshop repair technician, appliance installation technician, self-employed repairer", "ar": "فني صيانة أجهزة (خدمة ما بعد البيع أو مستقل)، فني خدمة ميدانية، فني ورشة إصلاح، فني تركيب أجهزة"}, "standards": "IEC 60335-1 and relevant Part 2 standards (e.g., -2-2 vacuum cleaners, -2-7 washing machines, -2-9 cooking appliances, -2-15 liquid heaters, -2-24 refrigerators, -2-25 microwave ovens), IEC 60034 (motors), national energy-label regulations, WEEE handling principles", "equipment": {"en": "Appliance repair benches with isolation transformers, PAT/appliance safety tester (earth continuity, insulation, leakage), motor test bench and small rewinding kit, washing-machine and dishwasher trainers, microwave leakage meter, induction and electronic board test jigs, refrigeration service kit", "ar": "طاولات إصلاح بمحولات عزل، جهاز اختبار سلامة الأجهزة، منصة اختبار محركات وطقم لف، وحدات تدريب للغسالات، مقياس تسرب الميكروويف، أدوات اختبار اللوحات"}, "tracks": [{"en": "Laundry & Kitchen Appliances", "ar": "أجهزة الغسيل والمطبخ"}, {"en": "Cooling & Air-Treatment Appliances", "ar": "أجهزة التبريد ومعالجة الهواء"}, {"en": "Smart & Electronic Appliances", "ar": "الأجهزة الذكية والإلكترونية"}], "capstone": {"en": "HAM Capstone: \"Run a Service Desk: Diagnose, Repair, Safety-Test and Hand Over Three Faulty Appliances\". The learner receives three customer complaints from different families (e.g., washing machine, microwave oven, refrigerator or smart appliance). For each, they (1) record the complaint and inspect; (2) diagnose using manuals, error codes and instruments; (3) quote and obtain approval; (4) repair; (5) perform and document the IEC 60335 safety test; (6) hand over with advice; then (7) present a cost and time analysis and defend the work. Duration: 80 h (System A) / 216 h (System B). Weighting: 40% of the final examination.", "ar": "مشروع التخرج: تشغيل مكتب خدمة: تشخيص وإصلاح واختبار سلامة وتسليم ثلاثة أجهزة معطلة. يتلقى المتدرب ثلاث شكاوى عملاء من عائلات أجهزة مختلفة (مثل غسالة أو فرن ميكروويف أو ثلاجة أو جهاز ذكي). ولكل منها: (1) يسجل الشكوى ويفحص الجهاز؛ (2) يشخص العطل باستخدام الأدلة وأكواد الأعطال وأجهزة القياس؛ (3) يقدم عرض السعر ويحصل على الموافقة؛ (4) يصلح الجهاز؛ (5) يجري اختبار السلامة وفق IEC 60335 ويوثقه؛ (6) يسلم الجهاز مع النصائح؛ ثم (7) يعرض تحليل التكلفة والوقت ويدافع عن عمله. المدة: 80 ساعة (النظام أ) / 216 ساعة (النظام ب). الوزن: 40٪ من الامتحان النهائي."}, "duration": {"en": "System A: 4,800 nominal hours · System B: 2,304 centre hours (576 / 864 / 864) + enterprise days", "ar": "النظام (أ): 4800 ساعة · النظام (ب): 2304 ساعة بالمركز"}, "pvtd": "صيانة الأجهزة المنزلية", "adopts": {"en": "ETF-Y1 (all), CPM-01 , CPM-02 , CPM-03 , CPM-04", "ar": "الأساس الكهروتقني كاملًا والوحدات المشتركة 01–04"}, "system_b": [["Year", "Sem.", "#", "Training Unit", "الوحدة التدريبية", "Mapped codes", "Hours"], ["Y1", "1", "1", "Occupational Safety & Health", "السلامة والصحة المهنية", "ETF-K-01, S-01", "32"], ["Y1", "1", "2", "Electricity Fundamentals", "أسس الكهرباء", "ETF-K-02, K-03, K-06, S-02, S-03", "112"], ["Y1", "1", "3", "Electronics Fundamentals", "أسس الإلكترونيات", "ETF-K-04, K-05, S-04…S-07", "112"], ["Y1", "1", "—", "Review & Test", "مراجعة واختبار", "", "32"], ["Y1", "2", "4", "Mechanical Operations", "عمليات التشغيل الميكانيكي", "CPM-02 , HAM-Y1-S-03", "96"], ["Y1", "2", "5", "Electrical Workshop Basics", "أساسيات ورشة الكهرباء", "CPM-03 , HAM-Y1-K-01 , S-01, S-02", "160"], ["Y1", "2", "—", "Review & Test", "مراجعة واختبار", "", "32"], ["", "", "", "Year 1 (identical to the PVTD Year 1 program)", "", "", "576"], ["Y2", "1", "6", "Appliance Motors & Rewinding", "محركات الأجهزة واللف", "HAM-Y2-K-01 , S-01", "168"], ["Y2", "1", "7", "Heating Appliances", "أجهزة التسخين", "K-02, S-02", "96"], ["Y2", "1", "8", "Motor-Driven Small Appliances", "الأجهزة الصغيرة ذات المحركات", "K-03, S-03", "120"], ["Y2", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y2", "2", "9", "Laundry & Dishwashing Appliances", "أجهزة الغسيل والجلي", "K-04, S-04", "192"], ["Y2", "2", "10", "Appliance Electronics & Control Boards", "إلكترونيات الأجهزة ولوحات التحكم", "K-05, S-05", "144"], ["Y2", "2", "11", "Domestic Refrigerators", "الثلاجات المنزلية", "K-06, S-06", "48"], ["Y2", "2", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["", "", "", "Year 2", "", "", "864"], ["Y3", "1", "12", "Microwave & Induction Cooking", "الميكروويف والطهي الحثي", "HAM-Y3-K-01 , S-01, S-02", "168"], ["Y3", "1", "13", "Air-Treatment & Cooling Appliances", "أجهزة معالجة الهواء والتبريد", "K-02", "144"], ["Y3", "1", "14", "Gas Appliance Safety", "سلامة الأجهزة الغازية", "K-03, S-03", "72"], ["Y3", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y3", "2", "15", "Smart Appliances & Energy Advice", "الأجهزة الذكية ونصح الطاقة", "K-04, K-05, S-04", "96"], ["Y3", "2", "16", "Service Business & Costing", "أعمال الخدمة والتكاليف", "K-06, K-07, S-06", "72"], ["Y3", "2", "17", "Capstone Project", "مشروع التخرج", "All Y3", "216"], ["Y3", "2", "—", "Review & Test / Final Trade Test", "مراجعة واختبار / اختبار المهنة النهائي", "", "48"], ["", "", "", "Year 3", "", "", "864"]], "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('oeq', 'OEQ', 'Office Equipment Maintenance', 'صيانة وإصلاح الأجهزة المكتبية', 'M6 9V3h12v6M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 14h12v7H6zM17 12h.01', 130, 'OEQ', '#5c7cfa',
  '{"occupation": {"en": "Office & Imaging Equipment Technician", "ar": "فني صيانة أجهزة مكتبية"}, "overview": {"en": "The Office Equipment Maintenance program prepares Office & Imaging Equipment Technicians (فني صيانة أجهزة مكتبية) to install, network, maintain, and repair printers, photocopiers and multifunction devices (MFPs), scanners, projectors and displays, point-of-sale and banking equipment (cash registers, barcode scanners, banknote counters), shredders, and uninterruptible power supplies. Government offices, banks, schools, hospitals, and retail chains depend on large fleets of such devices, usually serviced under contract. PVTD trains this occupation alongside Industrial Electronics with a shared electronic-drawing course; WABYS builds a full program around it, adding electrophotographic process knowledge, networked device configuration, managed print services, and responsible consumables handling.", "ar": "يُعد برنامج صيانة الأجهزة المكتبية فنيي الأجهزة المكتبية وأجهزة التصوير لتركيب الطابعات وآلات التصوير والأجهزة متعددة الوظائف والماسحات الضوئية وأجهزة العرض ونقاط البيع والأجهزة المصرفية (ماكينات تسجيل النقد، قارئات الباركود، عدادات النقود) وآلات الفرم ومصادر الطاقة غير المنقطعة، وربطها بالشبكة وصيانتها وإصلاحها. وتعتمد المصالح الحكومية والبنوك والمدارس والمستشفيات وسلاسل التجزئة على أعداد كبيرة من هذه الأجهزة تُصان عادة بعقود. وتُدرب مصلحة الكفاية الإنتاجية هذه المهنة مع الإلكترونيات الصناعية بكتاب رسم إلكتروني مشترك، وتبني وابيز حولها برنامجًا كاملًا."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Copier/MFP field technician, printer repair technician, POS and banking equipment technician, managed-print fleet technician, UPS service technician", "ar": "فني آلات تصوير وأجهزة متعددة الوظائف، فني إصلاح طابعات، فني أجهزة نقاط البيع والأجهزة المصرفية، فني إدارة أساطيل الطباعة، فني UPS"}, "standards": "IEC 62368-1 (safety of audio/video and ICT equipment), IEC 61340-5-1 (ESD), IEC 62040 (UPS), IEC 60617 (symbols), manufacturer service standards, WEEE and toner-waste handling principles", "equipment": {"en": "Laser printers and MFPs (mono and colour) for teardown, inkjet and thermal printers, scanners with ADF, projector and display bench, POS terminals and banknote counters, UPS trainer, ESD benches, toner vacuum, network switch and print server, fleet-monitoring software", "ar": "طابعات ليزر وأجهزة متعددة الوظائف للفك، طابعات نافثة وحرارية، ماسحات، أجهزة عرض، نقاط بيع وعدادات نقود، وحدة UPS، طاولات ESD، مكنسة أحبار، برنامج مراقبة الأسطول"}, "tracks": [{"en": "Print & Imaging", "ar": "الطباعة والتصوير"}, {"en": "Retail & Banking Equipment", "ar": "أجهزة التجزئة والبنوك"}, {"en": "Managed Print & Device Fleets", "ar": "خدمات الطباعة المدارة"}], "capstone": {"en": "OEQ Capstone: \"Commission and Hand Over an Office Device Fleet under a Service Contract\". For a real or simulated office of 30–100 users, the learner (1) audits existing devices and volumes; (2) recommends a fleet and service model with cost-per-page; (3) installs, networks and secures MFPs and printers; (4) sets up monitoring; (5) repairs two seeded faults; (6) trains key users and hands over; (7) defends the proposal and work. Duration: 80 h (System A) / 216 h (System B). Weighting: 40% of the final examination.", "ar": "مشروع التخرج: تشغيل وتسليم أسطول أجهزة مكتبية وفق عقد خدمة. لمكتب حقيقي أو افتراضي من 30 إلى 100 مستخدم يقوم المتدرب بما يلي: (1) يحصر الأجهزة الحالية وأحجام الطباعة؛ (2) يوصي بأسطول ونموذج خدمة مع تكلفة الصفحة؛ (3) يركب الطابعات والأجهزة متعددة الوظائف ويربطها بالشبكة ويؤمنها؛ (4) يجهز المراقبة؛ (5) يصلح عطلين مزروعين؛ (6) يدرب المستخدمين الرئيسيين ويسلم؛ (7) يدافع عن المقترح والعمل. المدة: 80 ساعة (النظام أ) / 216 ساعة (النظام ب). الوزن: 40٪ من الامتحان النهائي."}, "duration": {"en": "System A: 4,800 nominal hours · System B: 2,304 centre hours (576 / 864 / 864) + enterprise days", "ar": "النظام (أ): 4800 ساعة · النظام (ب): 2304 ساعة بالمركز"}, "pvtd": "صيانة وإصلاح الأجهزة المكتبية", "adopts": {"en": "ETF-Y1 (all), CPM-01 , CPM-02 , CPM-03 , CPM-04", "ar": "الأساس الكهروتقني كاملًا والوحدات المشتركة 01–04"}, "system_b": [["Year", "Sem.", "#", "Training Unit", "الوحدة التدريبية", "Mapped codes", "Hours"], ["Y1", "1", "1–3", "OSH · Electricity Fundamentals · Electronics Fundamentals", "السلامة · أسس الكهرباء · أسس الإلكترونيات", "ETF-Y1", "32 + 112 + 112"], ["Y1", "1", "—", "Review & Test", "مراجعة واختبار", "", "32"], ["Y1", "2", "4", "Mechanical Operations & Office Mechanisms", "التشغيل الميكانيكي وآليات الأجهزة المكتبية", "CPM-02 , OEQ-Y1-K-01 , S-01, S-02", "96"], ["Y1", "2", "5", "Electrical Workshop Basics", "أساسيات ورشة الكهرباء", "CPM-03", "160"], ["Y1", "2", "—", "Review & Test", "مراجعة واختبار", "", "32"], ["", "", "", "Year 1", "", "", "576"], ["Y2", "1", "6", "Electronic Circuit Drawing (shared with IEL)", "رسم الدوائر الإلكترونية (مشترك مع الإلكترونيات الصناعية)", "OEQ-Y2-K-01 , S-01", "72"], ["Y2", "1", "7", "Digital & Optoelectronics for Office Devices", "الإلكترونيات الرقمية والضوئية للأجهزة المكتبية", "K-02", "96"], ["Y2", "1", "8", "Power Supplies, Motors & Sensors", "مصادر التغذية والمحركات والحساسات", "K-03, S-02", "120"], ["Y2", "1", "9", "Printer Technologies I", "تقنيات الطابعات 1", "K-04", "96"], ["Y2", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y2", "2", "10", "Copiers & Multifunction Devices", "آلات التصوير والأجهزة متعددة الوظائف", "K-05, S-04", "192"], ["Y2", "2", "11", "Printer Service Practice", "ممارسة صيانة الطابعات", "K-04, S-03", "96"], ["Y2", "2", "12", "Device Networking & Drivers", "ربط الأجهزة بالشبكة", "K-06, S-05", "96"], ["Y2", "2", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["", "", "", "Year 2", "", "", "864"], ["Y3", "1", "13", "Projectors & Displays", "أجهزة العرض والشاشات", "OEQ-Y3-K-01 , S-01", "120"], ["Y3", "1", "14", "POS & Banking Equipment", "نقاط البيع والأجهزة المصرفية", "K-02, S-02", "144"], ["Y3", "1", "15", "UPS & Power Protection", "مصادر الطاقة غير المنقطعة", "K-03, S-03", "120"], ["Y3", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y3", "2", "16", "Managed Print & Fleet Monitoring", "الطباعة المدارة ومراقبة الأسطول", "K-04, S-04", "96"], ["Y3", "2", "17", "Environment, Contracts & Costing", "البيئة والعقود والتكاليف", "K-05, K-06, K-07, S-06", "72"], ["Y3", "2", "18", "Capstone Project", "مشروع التخرج", "All Y3", "216"], ["Y3", "2", "—", "Review & Test / Final Trade Test", "مراجعة واختبار / اختبار المهنة النهائي", "", "48"], ["", "", "", "Year 3", "", "", "864"]], "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('ave', 'AVE', 'Audio-Visual & Consumer Electronics', 'الإلكترونيات الاستهلاكية والسمعية والمرئية', 'M2 5h20v12H2zM8 21h8M12 17v4M10 9l4 2-4 2z', 140, 'AVE', '#ae3ec9',
  '{"occupation": {"en": "Consumer Electronics Technician", "ar": "فني إلكترونيات استهلاكية"}, "overview": {"en": "The Audio-Visual & Consumer Electronics program prepares Consumer Electronics Technicians (فني إلكترونيات استهلاكية) to install, repair, and configure televisions and displays, audio and public-address systems, satellite and terrestrial reception, smart-home entertainment, mobile devices, and CCTV and intercom systems. It modernizes the PVTD \"Radio, Television & Electronics\" occupation: analog radio and CRT content gives way to flat-panel displays, digital broadcasting (DVB-T2/S2), streaming, board-level SMD repair, and networked security systems, while keeping the occupation''s strong circuit-drawing and PCB foundations.", "ar": "يُعد برنامج الإلكترونيات الاستهلاكية والسمعية والمرئية فنيي الإلكترونيات الاستهلاكية لتركيب وإصلاح وتهيئة أجهزة التلفزيون والشاشات وأنظمة الصوت والإذاعة الداخلية واستقبال الأقمار الصناعية والبث الأرضي وأنظمة الترفيه المنزلي الذكية والأجهزة المحمولة وأنظمة المراقبة والاتصال الداخلي. ويحدّث البرنامج مهنة \"راديو وتليفزيون وإلكترونيات\" لدى مصلحة الكفاية الإنتاجية: فيحل محتوى الشاشات المسطحة والبث الرقمي والبث عبر الإنترنت وإصلاح اللوحات بتقنية SMD وأنظمة الأمن الشبكية محل محتوى الراديو التناظري وشاشات CRT، مع الاحتفاظ بأسس رسم الدوائر والدوائر المطبوعة."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "TV and display repair technician, AV installer, satellite/reception installer, mobile-device repair technician, CCTV and intercom installer", "ar": "فني إصلاح تلفزيونات وشاشات، مركّب أنظمة صوت وصورة، مركّب أطباق استقبال، فني إصلاح أجهزة محمولة، مركّب كاميرات مراقبة واتصال داخلي"}, "standards": "IEC 62368-1 (AV/ICT equipment safety), IEC 60268 (sound system equipment), IPC-A-610 and IPC-7711/7721 (assembly and rework), IEC 61340-5-1 (ESD), DVB-T2/DVB-S2, HDMI, IEC 62676 (video surveillance systems)", "equipment": {"en": "Electronics benches, SMD/BGA rework stations with microscope, display panel test jigs, signal and spectrum analyzers, satellite meter, audio analyzer and PA rack, mobile-repair kits, IP-CCTV kit with NVR, PCB CAD and fabrication", "ar": "طاولات إلكترونيات، محطات إعادة لحام SMD/BGA بمجهر، أدوات اختبار الشاشات، محللات إشارة وطيف، مقياس أقمار صناعية، محلل صوت، أطقم إصلاح المحمول، طقم مراقبة شبكية"}, "tracks": [{"en": "Display & Home Entertainment", "ar": "الشاشات والترفيه المنزلي"}, {"en": "Mobile Devices", "ar": "الأجهزة المحمولة"}, {"en": "Security & Professional AV", "ar": "الأمن والأنظمة الاحترافية"}], "capstone": {"en": "AVE Capstone: \"Repair, Install and Hand Over a Home Entertainment & Security System\". The learner (1) repairs a faulty flat-panel TV at board level; (2) designs and installs a home entertainment setup (display, sound bar or amplifier, reception, streaming); (3) installs a 4-camera IP-CCTV system with intercom; (4) prepares the estimate and documentation; (5) hands over to the customer and defends the work. Duration: 80 h (System A) / 192 h (System B). Weighting: 40% of the final examination.", "ar": "مشروع التخرج: إصلاح وتركيب وتسليم نظام ترفيه منزلي وأمن. يقوم المتدرب بما يلي: (1) يصلح شاشة مسطحة معطلة على مستوى اللوحات؛ (2) يصمم ويركب منظومة ترفيه منزلي (شاشة ومكبر صوت أو سماعة شريطية واستقبال وبث)؛ (3) يركب نظام مراقبة IP بأربع كاميرات مع إنتركم؛ (4) يعد المقايسة والتوثيق؛ (5) يسلم للعميل ويدافع عن العمل. المدة: 80 ساعة (النظام أ) / 192 ساعة (النظام ب). الوزن: 40٪ من الامتحان النهائي."}, "duration": {"en": "System A: 4,800 nominal hours · System B: 2,304 centre hours (576 / 864 / 864) + enterprise days", "ar": "النظام (أ): 4800 ساعة · النظام (ب): 2304 ساعة بالمركز"}, "pvtd": "راديو وتليفزيون وإلكترونيات", "adopts": {"en": "ETF-Y1 (all), CPM-01 , CPM-03 , CPM-04 ; IEL-Y2-K-05 (PCB) shared", "ar": "الأساس الكهروتقني، الوحدات 01 و03 و04، ووحدة الدوائر المطبوعة المشتركة"}, "system_b": [["Year", "Sem.", "#", "Training Unit", "الوحدة التدريبية", "Mapped codes", "Hours"], ["Y1", "1", "1–3", "OSH · Electricity Fundamentals · Electronics Fundamentals", "السلامة · أسس الكهرباء · أسس الإلكترونيات", "ETF-Y1", "32 + 112 + 112"], ["Y1", "1", "—", "Review & Test", "مراجعة واختبار", "", "32"], ["Y1", "2", "4", "Electronic Circuits for AV", "الدوائر الإلكترونية للأجهزة السمعية والمرئية", "AVE-Y1-K-01 , S-01, S-03", "112"], ["Y1", "2", "5", "Audio Fundamentals & Electrical Workshop", "أساسيات الصوت وورشة الكهرباء", "K-02, CPM-03 , S-02", "128"], ["Y1", "2", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["", "", "", "Year 1", "", "", "576"], ["Y2", "1", "6", "Electronic Circuit Drawing & PCB", "رسم الدوائر الإلكترونية والدوائر المطبوعة", "AVE-Y2-K-01 , S-01", "144"], ["Y2", "1", "7", "Radio Receivers", "أجهزة الاستقبال الراديوية", "K-02, S-02", "120"], ["Y2", "1", "8", "Digital Electronics & Microcontrollers", "الإلكترونيات الرقمية والمتحكمات", "K-03", "120"], ["Y2", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y2", "2", "9", "TV, Displays & Reception", "التلفزيون والشاشات والاستقبال", "K-04, S-03, S-05", "216"], ["Y2", "2", "10", "SMD Rework", "إعادة لحام SMD", "K-05, S-04", "96"], ["Y2", "2", "11", "Audio & Public Address", "الصوت والإذاعة الداخلية", "K-06, S-06", "72"], ["Y2", "2", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["", "", "", "Year 2", "", "", "864"], ["Y3", "1", "12", "Smart TV, Streaming & Home Networks", "التلفزيون الذكي والشبكات المنزلية", "AVE-Y3-K-01 , S-01", "96"], ["Y3", "1", "13", "Mobile Devices Repair", "إصلاح الأجهزة المحمولة", "K-02, S-02", "168"], ["Y3", "1", "14", "CCTV, Intercom & Security", "المراقبة والاتصال الداخلي والأمن", "K-03, S-03", "120"], ["Y3", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y3", "2", "15", "Professional AV", "الأنظمة الاحترافية", "K-04, S-04", "96"], ["Y3", "2", "16", "Firmware Tools, Estimating & Business", "أدوات البرامج والمقايسات والأعمال", "K-05, K-06, K-07, S-06", "96"], ["Y3", "2", "17", "Capstone Project", "مشروع التخرج", "All Y3", "192"], ["Y3", "2", "—", "Review & Test / Final Trade Test", "مراجعة واختبار / اختبار المهنة النهائي", "", "48"], ["", "", "", "Year 3", "", "", "864"]], "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;
INSERT INTO trades (id, code, name, name_ar, icon, sort_order, program_code, accent, profile) VALUES ('iem', 'IEM', 'Industrial Electricity & Electrical Machines', 'الكهرباء الصناعية والآلات الكهربية', 'M12 12m-6 0a6 6 0 1 0 12 0 6 6 0 1 0-12 0M12 12m-2 0a2 2 0 1 0 4 0 2 2 0 1 0-4 0M18 12h4M2 12h4', 150, 'IEM', '#fab005',
  '{"occupation": {"en": "Industrial Electrician", "ar": "كهربائي صناعي"}, "overview": {"en": "The Industrial Electricity & Electrical Machines program prepares Industrial Electricians (كهربائي صناعي) to install, connect, test, repair, rewind, and control the transformers, motors, generators, and drives that power factories, pumping stations, and utilities. It differs from Electrical Installations (ELI), which centres on building installations and automation: IEM centres on machines , including motor rewinding, which remains one of the most practical and employable skills in Egyptian industry. The program follows the PVTD Industrial Electricity syllabus (three-phase systems, transformers, three-phase and single-phase induction motors, DC machines, universal and stepper motors, rewinding) and adds industrial control panels, drives, protection, predictive maintenance, and motor energy efficiency.", "ar": "يُعد برنامج الكهرباء الصناعية والآلات الكهربية الكهربائيين الصناعيين لتركيب المحولات والمحركات والمولدات ووحدات القيادة التي تشغّل المصانع ومحطات الضخ والمرافق، وتوصيلها واختبارها وإصلاحها وإعادة لفها والتحكم فيها. ويختلف عن برنامج التركيبات الكهربية (ELI) الذي يركز على تركيبات المباني والأتمتة؛ إذ يركز هذا البرنامج على الآلات ، بما في ذلك لف المحركات الذي لا يزال من أكثر المهارات عملية وطلبًا في الصناعة المصرية. ويتبع البرنامج منهج الكهرباء الصناعية لدى مصلحة الكفاية الإنتاجية، ويضيف لوحات التحكم الصناعية ووحدات القيادة والحماية والصيانة التنبؤية وكفاءة طاقة المحركات."}, "eqf": "EQF 4", "hours": 4800, "occupations": {"en": "Industrial electrician, motor rewinder, electrical maintenance technician, control-panel builder, substation and transformer maintenance assistant", "ar": "كهربائي صناعي، فني لف محركات، فني صيانة كهربية، مُجمّع لوحات تحكم، مساعد صيانة محولات"}, "standards": "IEC 60034 series (rotating machines, incl. 60034-30-1 efficiency classes), IEC 60076 (power transformers), IEC 60947 (LV switchgear and controlgear), IEC 61439 (panels), IEC 60204-1 (machine electrical equipment), IEC 61131-3 (PLC), IEEE 43 (insulation resistance testing), NFPA 70E principles", "equipment": {"en": "Transformer and machine trainers (1-ph/3-ph transformers, induction, DC, universal, stepper motors), rewinding workshop (coil winders, slot-insulation and varnish oven), insulation tester and surge tester, motor-control benches, PLC/HMI and VFD trainers, power-factor correction panel, vibration pen and thermal camera", "ar": "وحدات تدريب محولات وآلات، ورشة لف (ماكينات لف، فرن ورنيش)، جهاز اختبار عزل وجهد صدمي، طاولات تحكم محركات، وحدات PLC وVFD، لوحة تحسين معامل القدرة، أجهزة اهتزاز وتصوير حراري"}, "tracks": [{"en": "Motor Rewinding & Machine Repair", "ar": "لف وإصلاح الآلات"}, {"en": "Industrial Control & Drives", "ar": "التحكم الصناعي ووحدات القيادة"}, {"en": "Power Distribution & Protection", "ar": "توزيع القوى والحماية"}], "capstone": {"en": "IEM Capstone: \"Overhaul, Rewind and Recommission a Motor Drive System\". The learner receives a failed three-phase motor and its control panel. They (1) test and record the failure; (2) record winding data, rewind and test the motor; (3) redesign the starter as a VFD or soft-starter panel with PLC control; (4) build and test the panel; (5) recommission the drive under load with energy measurements before and after; (6) prepare the cost comparison (rewind vs. replace with IE3) and documentation; (7) defend the project. Duration: 80 h (System A) / 168 h (System B). Weighting: 40% of the final examination.", "ar": "مشروع التخرج: عَمرة وإعادة لف وإعادة تشغيل منظومة قيادة محرك. يتلقى المتدرب محركًا ثلاثي الأوجه معطلًا ولوحة التحكم الخاصة به، ثم: (1) يختبر العطل ويسجله؛ (2) يسجل بيانات اللف ويعيد لف المحرك ويختبره؛ (3) يعيد تصميم البادئ كلوحة مغير سرعة أو بادئ ناعم بتحكم PLC؛ (4) يبني اللوحة ويختبرها؛ (5) يعيد تشغيل المنظومة تحت الحمل مع قياسات الطاقة قبل وبعد؛ (6) يعد مقارنة التكلفة (إعادة اللف مقابل الاستبدال بمحرك IE3) والتوثيق؛ (7) يدافع عن المشروع. المدة: 80 ساعة (النظام أ) / 168 ساعة (النظام ب). الوزن: 40٪ من الامتحان النهائي."}, "duration": {"en": "System A: 4,800 nominal hours · System B: 2,304 centre hours (576 / 864 / 864) + enterprise days", "ar": "النظام (أ): 4800 ساعة · النظام (ب): 2304 ساعة بالمركز"}, "pvtd": "الكهرباء الصناعية", "adopts": {"en": "ETF-Y1 (all), CPM-01 , CPM-02 , CPM-03 , CPM-04", "ar": "الأساس الكهروتقني كاملًا والوحدات المشتركة 01–04"}, "system_b": [["Year", "Sem.", "#", "Training Unit", "الوحدة التدريبية", "Mapped codes", "Hours"], ["Y1", "1", "1–3", "OSH · Electricity Fundamentals · Electronics Fundamentals", "السلامة · أسس الكهرباء · أسس الإلكترونيات", "ETF-Y1", "32 + 112 + 112"], ["Y1", "1", "—", "Review & Test", "مراجعة واختبار", "", "32"], ["Y1", "2", "4", "Mechanical Operations", "عمليات التشغيل الميكانيكي", "CPM-02", "96"], ["Y1", "2", "5", "Electrical Workshop Basics & Industrial Drawing", "أساسيات ورشة الكهرباء والرسم الصناعي", "CPM-03 , IEM-Y1-K-01 , S-01, S-02", "160"], ["Y1", "2", "—", "Review & Test", "مراجعة واختبار", "", "32"], ["", "", "", "Year 1", "", "", "576"], ["Y2", "1", "6", "Three-Phase Systems & Transformers", "الأنظمة ثلاثية الأوجه والمحولات", "IEM-Y2-K-01 , K-02, S-01", "144"], ["Y2", "1", "7", "Three-Phase Induction Motors", "المحركات الحثية ثلاثية الأوجه", "K-03, S-02", "144"], ["Y2", "1", "8", "Single-Phase Motors", "المحركات أحادية الوجه", "K-04, S-04", "96"], ["Y2", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y2", "2", "9", "DC, Universal & Stepper Motors", "محركات التيار المستمر والعام والخطوة", "K-05, K-06, S-05, S-07", "120"], ["Y2", "2", "10", "Motor Rewinding", "لف المحركات", "K-07, S-03", "168"], ["Y2", "2", "11", "Industrial Motor Control", "التحكم الصناعي في المحركات", "K-08, S-06", "96"], ["Y2", "2", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["", "", "", "Year 2 (theory taught as the general subject \"Electrical Engineering 2\", 108 periods, 3/week)", "", "", "864"], ["Y3", "1", "12", "PLC & HMI", "PLC وواجهات التشغيل", "IEM-Y3-K-01 , S-01", "168"], ["Y3", "1", "13", "Drives", "وحدات القيادة", "K-02, S-02", "120"], ["Y3", "1", "14", "Control-Panel Building", "تجميع لوحات التحكم", "K-03, S-03", "96"], ["Y3", "1", "—", "Review & Test", "مراجعة واختبار", "", "48"], ["Y3", "2", "15", "Protection & Power-Factor Correction", "الحماية وتحسين معامل القدرة", "K-04, S-04", "72"], ["Y3", "2", "16", "Predictive Maintenance of Machines", "الصيانة التنبؤية للآلات", "K-05, S-05", "96"], ["Y3", "2", "17", "Energy Efficiency & Costing", "كفاءة الطاقة والتكاليف", "K-06, K-07, S-07", "48"], ["Y3", "2", "18", "Capstone Project", "مشروع التخرج", "All Y3", "168"], ["Y3", "2", "—", "Review & Test / Final Trade Test", "مراجعة واختبار / اختبار المهنة النهائي", "", "48"], ["", "", "", "Year 3", "", "", "864"]], "source": {"en": "WABYS Manual for Vocational Education & Applied Technology Curriculums, First Edition 2026, Revision 1.1 (October 2026)", "ar": "دليل وابيز لأطر مناهج التدريب المهني والتعليم التكنولوجي، الطبعة الأولى 2026، المراجعة 1.1 (أكتوبر 2026)"}, "revision": "1.1"}'::jsonb)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, name_ar = EXCLUDED.name_ar, program_code = EXCLUDED.program_code, accent = EXCLUDED.accent, profile = EXCLUDED.profile;

