-- Elements: knowledge modules, skill competencies and attitudes (ETF-… and CPM-… are the shared units)
INSERT INTO competencies (framework_id, parent_id, code, title, title_ar, description, description_ar, kind, ksa, year, nominal_hours,
                          target_level, core_attitude, is_safety_critical, sort_order)
SELECT f.id, p.id, v.code, v.title, v.title_ar, v.descr, v.descr_ar, 'element', v.ksa, v.year, v.hours, v.lvl, v.core, v.safety, v.sort
  FROM (VALUES
  ('WABYS-IEL-2026', 'ETF-Y1-K-01', 'IEL-Y1-K', 'Occupational Safety & Health for Electrical and Electronic Work', 'السلامة والصحة المهنية في الأعمال الكهربية والإلكترونية', 'OSH concepts and the HSE management system; workplace lighting and ventilation; manual handling; PPE (head, face, eyes, hearing, respiratory, hands, feet, fall protection); fire triangle, fire classes and extinguisher types; safety signs; electrical hazards (shock, burns, arc flash, fire); rescuing a casualty from circuits below and above 1,000 V; the five safety rules and LOTO; ESD protection; ergonomics of computer work; first aid', 'معامل استنفاد الأوزون وقدرة الاحترار العالمي؛ إضاءة مكان العمل وتهويته؛ المناولة اليدوية؛ معدات الوقاية الشخصية (الرأس والوجه والعينين والسمع والتنفس واليدين والقدمين والحماية من السقوط)؛ مثلث الحريق وفئات الحرائق وأنواع الطفايات؛ علامات السلامة؛ المخاطر الكهربائية (الصدمة والحروق والقوس الكهربائي والحريق)؛ إنقاذ المصاب من دوائر أقل وأعلى من 1000 فولت؛ قواعد السلامة الخمس والإقفال ووضع البطاقات؛ تطبيق احتياطات التفريغ الكهروستاتيكي؛ بيئة العمل المريحة على الحاسب؛ الإسعافات الأولية', 'K', 1, 40, NULL, NULL, false, 1),
  ('WABYS-IEL-2026', 'ETF-Y1-K-02', 'IEL-Y1-K', 'DC Circuits & Passive Components', 'دوائر التيار المستمر والعناصر الخاملة', 'Charge, voltage, current, resistance, power; Ohm''s law; Kirchhoff''s current and voltage laws; current and voltage dividers; resistor types, color code, series/parallel/compound; LDR and NTC/PTC; fuses', 'يغطي فتحات المواسير؛ قانون أوم؛ حساب تكلفة العمل؛ مقسمات التيار والجهد؛ أنواع المقاومات وكود الألوان والتوالي والتوازي والمركب؛ جهاز قياس LCR؛ المصهرات', 'K', 1, 50, NULL, NULL, false, 2),
  ('WABYS-IEL-2026', 'ETF-Y1-K-03', 'IEL-Y1-K', 'AC Circuits, Capacitors, Inductors & Transformers', 'دوائر التيار المتردد والمكثفات والملفات والمحولات', 'Sinusoidal quantities; capacitors and coils (types, codes, series/parallel); charge/discharge and time constant; effect of AC on R, L and C; reactance and impedance; single-phase transformer principle and testing', 'الكميات الجيبية؛ المكثفات والملفات (الأنواع والأكواد والتوالي والتوازي)؛ الشحن والتفريغ والثابت الزمني؛ تأثير التيار المتردد على المقاومة والملف والمكثف؛ المفاعلة والمعاوقة؛ مبدأ المحول أحادي الوجه واختباره', 'K', 1, 40, NULL, NULL, false, 3),
  ('WABYS-IEL-2026', 'ETF-Y1-K-04', 'IEL-Y1-K', 'Analog Electronics Fundamentals', 'أساسيات الإلكترونيات التناظرية', 'Atom and semiconductors; PN junction, forward/reverse bias; diode characteristics; half- and full-wave rectifiers; Zener diode; LED; BJT operation, currents, parameters; BJT as switch; op-amp as inverting and non-inverting amplifier', 'الذرة وأشباه الموصلات؛ الوصلة الثنائية، الانحياز الأمامي والعكسي؛ خصائص الديود؛ موحدات نصف الموجة والموجة الكاملة؛ ديود زينر؛ المقاومة الضوئية والليد والديود الضوئي والترانزستور الضوئي والعازل الضوئي والثايرستور الضوئي؛ تشغيل الترانزستور ثنائي القطبية وتياراته ومعاملاته؛ الترانزستور ثنائي القطبية كمفتاح؛ مكبر العمليات كمكبر عاكس وغير عاكس', 'K', 1, 50, NULL, NULL, false, 4),
  ('WABYS-IEL-2026', 'ETF-Y1-K-05', 'IEL-Y1-K', 'Digital Electronics Fundamentals', 'أساسيات الإلكترونيات الرقمية', 'Decimal, binary, octal and hexadecimal systems; binary arithmetic; logic gates (AND, OR, NOT, NAND, NOR, XOR, XNOR); input/output interfaces; combinational logic (half adder, 2-bit comparator); sequential logic (SR latch, D and JK flip-flops)', 'نشرات البيانات وأدلة الصيانة؛ الحساب الثنائي؛ البوابات المنطقية (AND وOR وNOT وNAND وNOR وXOR وXNOR)؛ واجهات الإدخال والإخراج؛ المنطق التوافقي (نصف الجامع والمقارن ثنائي البت)؛ المنطق التتابعي (الماسك SR والقلابات D وJK)', 'K', 1, 40, NULL, NULL, false, 5),
  ('WABYS-IEL-2026', 'ETF-Y1-K-06', 'IEL-Y1-K', 'Test & Measurement Instruments', 'أجهزة الاختبار والقياس', 'Multimeter (AVO) and clamp meter; LCR meter; DC power supply; function generator; oscilloscope (controls, calibration, reading amplitude, period, phase); measurement categories (CAT II–IV); errors and tolerance; simulation software', 'بروتوكول مونتريال وتعديل كيغالي؛ أجهزة العرض LCD وDLP والليزر؛ التحكم في محرك التيار المستمر؛ مولد الموجات؛ راسم الموجات (أدوات التحكم والمعايرة وقراءة السعة والزمن الدوري والطور)؛ فئات القياس (CAT II–IV)؛ الأخطاء والسماحية؛ برامج المحاكاة', 'K', 1, 30, NULL, NULL, false, 6),
  ('WABYS-IEL-2026', 'CPM-01', 'IEL-Y1-K', 'Computer & IT Principles', 'مبادئ الحاسب وتكنولوجيا المعلومات', 'Computer structure, classification and components; internet, browsers and e-mail; word processing (formatting, tables, images, proofing, page setup, printing); spreadsheets (formatting, formulas and functions, charts, print setup); presentations; WABYS additions: cloud storage and file management, password and MFA hygiene, safe use of AI assistants', 'محركات الضواغط؛ الإنترنت والمتصفحات والبريد الإلكتروني؛ معالجة النصوص (التنسيق والجداول والصور والتدقيق وإعداد الصفحة والطباعة)؛ جداول البيانات (التنسيق والمعادلات والدوال والرسوم البيانية وإعداد الطباعة)؛ العروض التقديمية؛ إضافات وابيز: التخزين السحابي وإدارة الملفات، ونظافة كلمات المرور والتحقق المتعدد، والاستخدام الآمن للمساعدات الذكية', 'K', 1, 54, NULL, NULL, false, 7),
  ('WABYS-IEL-2026', 'IEL-Y1-K-01', 'IEL-Y1-K', 'Basic Electronic Circuits', 'دوائر الإلكترونيات الأساسية', 'Semiconductor numbering systems (JEDEC, Pro-Electron); BJT as a switch; BJT amplifier configurations and biasing; RC, LC and crystal oscillators; trigger circuits (Schmitt trigger, 555 astable/monostable)', 'أنظمة ترقيم أشباه الموصلات (JEDEC وPro-Electron)؛ الترانزستور ثنائي القطبية كمفتاح؛ توصيلات مكبر الترانزستور ثنائي القطبية وانحيازه؛ مذبذبات RC وLC والبلورية؛ دوائر القدح (قادح شميت، 555 غير مستقر وأحادي الاستقرار)', 'K', 1, 60, NULL, NULL, false, 8),
  ('WABYS-IEL-2026', 'IEL-Y1-K-02', 'IEL-Y1-K', 'Analog Electronics & Op-Amp Control', 'الإلكترونيات التماثلية والتحكم بمكبر العمليات', 'Op-amp symbol, characteristics and transfer curve; inverting, non-inverting, comparator, summing and subtracting circuits; op-amp controllers: P, I, D, PI, PD and PID; closed-loop principles', 'رمز مكبر العمليات وخصائصه ومنحنى النقل؛ دوائر العاكس وغير العاكس والمقارن والجامع والطارح؛ متحكمات مكبر العمليات: P وI وD وPI وPD وPID؛ مبادئ الحلقة المغلقة', 'K', 1, 60, NULL, NULL, false, 9),
  ('WABYS-IEL-2026', 'IEL-Y1-K-03', 'IEL-Y1-K', 'Electronic Drawing & Symbols', 'الرسم الإلكتروني والرموز', 'IEC 60617 symbols; schematic, block and wiring diagrams; component outlines; reading manufacturer schematics', 'رموز IEC 60617؛ المخططات الصندوقية ومخططات الدوائر والتوصيل؛ المسقط الخارجي للمكونات؛ قراءة مخططات الشركات المصنعة', 'K', 1, 40, NULL, NULL, false, 10),
  ('WABYS-IEL-2026', 'IEL-Y1-K-04', 'IEL-Y1-K', 'Technical Mathematics & English for Electronics', 'الرياضيات والإنجليزية الفنية للإلكترونيات', 'Powers of ten and prefixes; logarithms and decibels; phasors; datasheet vocabulary and reading', 'قوى العشرة والبادئات؛ اللوغاريتمات والديسيبل؛ المتجهات الطورية؛ مفردات نشرات البيانات وقراءتها', 'K', 1, 50, NULL, NULL, false, 11),
  ('WABYS-IEL-2026', 'ETF-Y1-S-01', 'IEL-Y1-S', 'Work safely and give first aid', 'العمل بأمان وتقديم الإسعافات الأولية', 'Workplace hazards checked; correct PPE; extinguisher selected and operated in drill; casualty freed from LV circuit by correct method; first-aid simulation passed', 'فحص مخاطر مكان العمل؛ معدات وقاية صحيحة؛ اختيار الطفاية وتشغيلها في التدريب؛ تحرير المصاب من دائرة جهد منخفض بالطريقة الصحيحة؛ اجتياز محاكاة الإسعافات الأولية', 'S', 1, NULL, 'L3', NULL, true, 1),
  ('WABYS-IEL-2026', 'ETF-Y1-S-02', 'IEL-Y1-S', 'Build and verify DC circuits', 'بناء دوائر التيار المستمر والتحقق منها', 'Circuits built on breadboard; Ohm''s, Kirchhoff''s and divider rules verified with measured values within ±5% of calculation; fuse protection applied', 'توصيل الدائرة من الرسم شاملة الضاغط والمراوح وإذابة الثلج والترموستات؛ التحقق من قوانين أوم وكيرشوف ومقسم الجهد بقيم مقاسة ضمن ±5% من الحساب؛ تطبيق الحماية بالمصهرات', 'S', 1, NULL, 'L3', NULL, false, 2),
  ('WABYS-IEL-2026', 'ETF-Y1-S-03', 'IEL-Y1-S', 'Measure AC components and signals', 'قياس عناصر وإشارات التيار المتردد', 'C and L values read with LCR meter; RC charge curve and AC phase shift observed on oscilloscope; transformer ratio tested', 'قراءة قيم المكثفات والملفات بجهاز LCR؛ مشاهدة منحنى شحن RC وإزاحة الطور في التيار المتردد على راسم الموجات؛ اختبار نسبة التحويل في المحول', 'S', 1, NULL, 'L3', NULL, false, 3),
  ('WABYS-IEL-2026', 'ETF-Y1-S-04', 'IEL-Y1-S', 'Build rectifier and regulated supply circuits', 'بناء دوائر التوحيد ومصادر التغذية المنظمة', 'Half-wave, full-wave and bridge rectifiers built; ripple measured; Zener regulation verified; LED with correct series resistor', 'تفريغ مكثف الجهد العالي والتحقق من ذلك؛ قياس التموج؛ التحقق من تنظيم الجهد بالزينر؛ الليد (LED)', 'S', 1, NULL, 'L3', NULL, false, 4),
  ('WABYS-IEL-2026', 'ETF-Y1-S-05', 'IEL-Y1-S', 'Apply transistor switches and op-amp amplifiers', 'تطبيق الترانزستور كمفتاح ومكبرات العمليات', 'NPN switch drives a load; inverting and non-inverting gains measured within ±10% of design', 'NAT؛ قياس كسب المكبر العاكس وغير العاكس ضمن ±10% من التصميم', 'S', 1, NULL, 'L2', NULL, false, 5),
  ('WABYS-IEL-2026', 'ETF-Y1-S-06', 'IEL-Y1-S', 'Build and test logic circuits', 'بناء الدوائر المنطقية واختبارها', 'Truth tables of all basic gates verified; half adder, comparator, SR latch, D and JK flip-flops function correctly', 'التحقق من جداول الحقيقة لجميع البوابات الأساسية؛ نصف الجامع والمقارن والماسك SR والقلابات D وJK تعمل بشكل صحيح', 'S', 1, NULL, 'L3', NULL, false, 6),
  ('WABYS-IEL-2026', 'ETF-Y1-S-07', 'IEL-Y1-S', 'Solder and desolder electronic components', 'لحام المكونات الإلكترونية وفكها', 'Through-hole joints clean and conical, no bridges or cold joints; component removed without pad damage; introduction to SMD rework', 'وصلات المكونات المثقوبة نظيفة ومخروطية دون جسور أو لحام بارد؛ فك المكون دون تلف المسارات؛ مقدمة في إعادة لحام المكونات السطحية', 'S', 1, NULL, 'L2', NULL, false, 7),
  ('WABYS-IEL-2026', 'CPM-01-S', 'IEL-Y1-S', 'Produce a technical document set', 'إعداد مجموعة وثائق فنية', 'Formatted report with table and image, spreadsheet with formulas and chart, 5-slide presentation; files named and stored in shared folder', 'عوامل الشكل؛ تسمية الملفات وحفظها في المجلد المشترك', 'S', 1, NULL, 'L3', NULL, false, 8),
  ('WABYS-IEL-2026', 'IEL-Y1-S-01', 'IEL-Y1-S', 'Build and test transistor amplifiers', 'بناء واختبار مكبرات الترانزستور', 'Bias point within ±10% of design; voltage gain and bandwidth measured with oscilloscope and recorded', 'نقطة الانحياز ضمن ±10% من التصميم؛ قياس كسب الجهد وعرض النطاق براسم الموجات وتسجيلهما', 'S', 1, NULL, 'L3', NULL, false, 9),
  ('WABYS-IEL-2026', 'IEL-Y1-S-02', 'IEL-Y1-S', 'Build oscillator and timing circuits', 'بناء دوائر المذبذبات والتوقيت', 'RC/LC oscillator and 555 circuits produce specified frequency within ±10%; waveforms documented', 'مذبذب RC/LC ودوائر 555 تعطي التردد المحدد ضمن ±10%؛ توثيق أشكال الموجات', 'S', 1, NULL, 'L3', NULL, false, 10),
  ('WABYS-IEL-2026', 'IEL-Y1-S-03', 'IEL-Y1-S', 'Build op-amp signal circuits', 'بناء دوائر الإشارة بمكبر العمليات', 'Comparator, summer and subtractor function to specification; offset and saturation observed and explained', 'خرط المجمع (الكوميوتاتور) أو تنظيفه؛ ملاحظة الإزاحة والتشبع وتفسيرهما', 'S', 1, NULL, 'L3', NULL, false, 11),
  ('WABYS-IEL-2026', 'IEL-Y1-S-04', 'IEL-Y1-S', 'Implement an op-amp PID control loop', 'تنفيذ حلقة تحكم PID بمكبر العمليات', 'P, PI and PID responses of a temperature or speed trainer recorded; effect of each term explained', 'تسجيل استجابات P وPI وPID لوحدة تدريب الحرارة أو السرعة؛ شرح تأثير كل حد', 'S', 1, NULL, 'L2', NULL, false, 12),
  ('WABYS-IEL-2026', 'IEL-Y1-S-05', 'IEL-Y1-S', 'Read and draw electronic schematics', 'قراءة ورسم المخططات الإلكترونية', 'Schematic drawn to IEC 60617 from a real board; parts list complete', 'رسم المخطط وفق IEC 60617 من لوحة حقيقية؛ قائمة المكونات كاملة', 'S', 1, NULL, 'L3', NULL, false, 13),
  ('WABYS-IEL-2026', 'ETF-Y1-A-01', 'IEL-Y1-A', 'Test before touch; ESD discipline', 'الاختبار قبل اللمس والانضباط ضد الكهرباء الساكنة', 'Verifies de-energized state; wears wrist strap on electronic benches', 'يتحقق من فصل التيار؛ يرتدي سوار التفريغ على طاولات الإلكترونيات', 'A', 1, NULL, NULL, 'A1', false, 1),
  ('WABYS-IEL-2026', 'ETF-Y1-A-02', 'IEL-Y1-A', 'Honest measurement', 'الأمانة في القياس', 'Records actual readings with units; never "adjusts" results to theory', 'يسجل القراءات الفعلية بوحداتها؛ لا "يعدّل" النتائج أبدًا لتطابق النظرية', 'A', 1, NULL, NULL, 'A3', false, 2),
  ('WABYS-IEL-2026', 'ETF-Y1-A-03', 'IEL-Y1-A', 'E-waste responsibility', 'المسؤولية تجاه المخلفات الإلكترونية', 'Separates components, solder dross and batteries for proper disposal', 'يفصل المكونات وبقايا القصدير والبطاريات للتخلص الصحيح', 'A', 1, NULL, NULL, 'A6', false, 3),
  ('WABYS-IEL-2026', 'ETF-Y1-A-04', 'IEL-Y1-A', 'Bench readiness', 'جاهزية طاولة العمل', 'Prepares instruments, returns them calibrated and switched off', 'يجهز الأجهزة ويعيدها مطفأة وسليمة', 'A', 1, NULL, NULL, 'A2', false, 4),
  ('WABYS-IEL-2026', 'IEL-Y1-A-01', 'IEL-Y1-A', 'Mains and ESD discipline', 'الانضباط مع جهد الشبكة والكهرباء الساكنة', 'Uses isolation transformer for mains-powered boards; ESD strap always worn', 'يستخدم محول عزل للوحات الموصلة بالشبكة؛ الحماية من التفريغ الكهروستاتيكي', 'A', 1, NULL, NULL, 'A1', false, 5),
  ('WABYS-IEL-2026', 'IEL-Y1-A-02', 'IEL-Y1-A', 'Measured, not guessed', 'القياس لا التخمين', 'Confirms every assumption with a measurement before replacing parts', 'يؤكد كل افتراض بالقياس قبل استبدال المكونات', 'A', 1, NULL, NULL, 'A3', false, 6),
  ('WABYS-IEL-2026', 'IEL-Y1-A-03', 'IEL-Y1-A', 'Bench sharing', 'مشاركة طاولة العمل', 'Shares instruments fairly; explains readings to partner', 'يتشارك الأجهزة بعدل؛ يشرح القراءات لزميله', 'A', 1, NULL, NULL, 'A4', false, 7),
  ('WABYS-IEL-2026', 'IEL-Y1-A-04', 'IEL-Y1-A', 'Technical curiosity', 'الفضول التقني', 'Looks up datasheets independently; asks "why" about circuit behavior', 'المنطق والمؤقتات والعدادات والمقارنات تحقق الوصف الوظيفي؛ يسأل "لماذا" عن سلوك الدائرة', 'A', 1, NULL, NULL, 'A7', false, 8),
  ('WABYS-IEL-2026', 'CPM-04', 'IEL-Y2-K', 'Production Quality Control', 'مراقبة جودة الإنتاج', 'Quality definitions, functions and influencing factors; characteristics and specifications; the quality cycle and responsibilities; ISO 9001:2015 and Total Quality Management (benefits, stages of quality assurance, certification requirements); inspection duties and types; sampling inspection and sampling plans (AQL); the seven basic quality tools (check sheet, Pareto, cause-and-effect, scatter diagram, histogram, control charts, graphs); link to 5S and Kaizen ( CWS-Y2-K-08 )', 'تعريفات الجودة ووظائفها والعوامل المؤثرة فيها؛ الخصائص والمواصفات؛ دورة الجودة والمسؤوليات؛ رموز ISO 1219؛ مهام الفحص وأنواعه؛ الفحص بالعينات وخطط المعاينة (AQL)؛ أدوات الجودة السبع الأساسية (ورقة التحقق، باريتو، السبب والنتيجة، مخطط الانتشار، المدرج التكراري، خرائط التحكم، الرسوم البيانية)؛ الارتباط بـ 5S والكايزن (CWS-Y2-K-08)', 'K', 2, 30, NULL, NULL, false, 1),
  ('WABYS-IEL-2026', 'IEL-Y2-K-01', 'IEL-Y2-K', 'Digital Electronics', 'الإلكترونيات الرقمية', 'Boolean algebra and Karnaugh maps; code conversion (binary, octal, hex, BCD); binary arithmetic, adders, subtractors, multipliers; flip-flops; synchronous and asynchronous counters; shift registers; ADC/DAC (R-2R); MUX/DEMUX; fault-finding in digital circuits', 'الجبر البولياني وخرائط كارنو؛ تحويل الشفرات (ثنائي وثماني وست عشري وBCD)؛ الحساب الثنائي والجوامع والطوارح والمضاعفات؛ القلابات؛ العدادات المتزامنة وغير المتزامنة؛ مسجلات الإزاحة؛ محولات ADC/DAC ‏(شبكة R-2R)؛ MQTT؛ تتبع الأعطال في الدوائر الرقمية', 'K', 2, 60, NULL, NULL, false, 2),
  ('WABYS-IEL-2026', 'IEL-Y2-K-02', 'IEL-Y2-K', 'Optoelectronics & Displays', 'الإلكترونيات الضوئية ووحدات العرض', 'Photoemission; LDR, LED, photodiode, phototransistor, optocoupler, photo-thyristor; 7-segment, VFD and LCD displays; optical isolation', 'الانبعاث الضوئي؛ المقاومة الضوئية وثرمستورات NTC/PTC؛ شاشات السبع قطع وVFD وLCD؛ العزل الضوئي', 'K', 2, 30, NULL, NULL, false, 3),
  ('WABYS-IEL-2026', 'IEL-Y2-K-03', 'IEL-Y2-K', 'Power Electronics I', 'إلكترونيات القوى 1', 'SCR, TRIAC, DIAC characteristics and testing; uncontrolled and controlled rectifiers; phase control; zero-voltage switching; light dimmers; MOSFET and IGBT switching basics; heat sinking', 'خصائص الثايرستور والترياك والدياك واختبارها؛ الموحدات غير المحكومة والمحكومة؛ التحكم بالطور؛ التبديل عند الجهد الصفري؛ معتمات الإضاءة؛ يبحث عن نشرات البيانات باستقلالية؛ تبديد الحرارة بالمشتتات', 'K', 2, 50, NULL, NULL, false, 4),
  ('WABYS-IEL-2026', 'IEL-Y2-K-04', 'IEL-Y2-K', 'PLC for Electronic Systems', 'المتحكمات المنطقية المبرمجة للأنظمة الإلكترونية', 'PLC safety; architecture and types; I/O; logic instructions, timers, counters, comparators; DC motor control; simulators; IEC 61131-3', 'سلامة PLC؛ البنية والأنواع؛ المداخل والمخارج؛ التعليمات المنطقية والمؤقتات والعدادات والمقارنات؛ وحدات قيادة محركات التيار المستمر؛ المحاكيات؛ فئات الكفاءة IE1–IE4 ‏(IEC 60034-30-1)', 'K', 2, 50, NULL, NULL, false, 5),
  ('WABYS-IEL-2026', 'IEL-Y2-K-05', 'IEL-Y2-K', 'PCB Design & Fabrication', 'تصميم وتصنيع الدوائر المطبوعة', 'Schematic capture and layout in CAD; IPC-2221 track and clearance rules; single/double-sided boards; Gerber output; photo-printing, UV exposure, etching and safe chemical handling; drilling; SMD and through-hole assembly to IPC-A-610', 'رسم المخطط وتصميم اللوحة ببرنامج التصميم؛ ضبط عنوان IP؛ لوحات أحادية أو مزدوجة الوجه؛ التروس والبكرات والسيور والكامات والزنبركات والملفات اللولبية والقوابض؛ الطباعة الضوئية والتعريض بالأشعة فوق البنفسجية والحفر والتعامل الآمن مع الكيماويات؛ الثقب؛ تجميع المكونات السطحية والمثقوبة وفق IPC-A-610', 'K', 2, 40, NULL, NULL, false, 6),
