  ('WABYS-IEL-2026', 'IEL-Y2-S-03', 'IEL-Y2-S', 'Build and test power-control circuits', 'بناء واختبار دوائر التحكم في القدرة', 'SCR/TRIAC tested; phase-control dimmer and controlled rectifier built and measured under load; isolation and fusing correct', 'اختبار الثايرستور والترياك؛ بناء معتم بالتحكم في الطور وموحد محكوم وقياسهما تحت الحمل؛ العزل والحماية بالمصهرات صحيحان', 'S', 2, NULL, 'L3', NULL, false, 4),
  ('WABYS-IEL-2026', 'IEL-Y2-S-04', 'IEL-Y2-S', 'Program PLC control functions', 'برمجة وظائف التحكم بـ PLC', 'Logic, timers, counters and comparators meet functional description; DC motor controlled; program commented', 'المنطق والذاكرة والنواقل؛ التحكم في محرك التيار المستمر؛ البرنامج مزود بالتعليقات', 'S', 2, NULL, 'L3', NULL, false, 5),
