  ('WABYS-IEL-2026', 'IEL-Y3-K-07', 'IEL-Y3-K', 'Entrepreneurship for Electronics Services', 'ريادة الأعمال في خدمات الإلكترونيات', 'Repair-shop and contract-manufacturing models; warranties; component sourcing and anti-counterfeit practice', 'نماذج ورش الإصلاح والتصنيع التعاقدي؛ الضمانات؛ توريد المكونات وممارسات مكافحة التقليد', 'K', 3, 20, NULL, NULL, false, 7),
  ('WABYS-IEL-2026', 'IEL-Y3-S-01', 'IEL-Y3-S', 'Install and calibrate sensors with signal conditioning', 'تركيب الحساسات ومعايرتها مع تهيئة الإشارة', 'Sensor selected for the quantity; 4–20 mA loop scaled and calibrated within ±1% of span; calibration record completed', 'اختيار الحساس المناسب للكمية المقاسة؛ معايرة حلقة 4–20 مللي أمبير وتدريجها بدقة ±1% من المدى؛ إكمال سجل المعايرة', 'S', 3, NULL, 'L3', NULL, false, 1),
  ('WABYS-IEL-2026', 'IEL-Y3-S-02', 'IEL-Y3-S', 'Program an embedded control system', 'برمجة نظام تحكم مدمج', 'Microcontroller reads sensors, drives outputs via PWM, communicates over UART/I²C; code versioned and commented', 'تطبيق المنهجية؛ إدارة إصدارات الكود والتعليق عليه', 'S', 3, NULL, 'L3', NULL, false, 2),
