  ('WABYS-IEL-2026', 'IEL-Y3-A-01', 'IEL-Y3-A', 'Functional-safety awareness', 'الوعي بالسلامة الوظيفية', 'Never bypasses interlocks or safety sensors, even temporarily', 'لا يتجاوز وسائل الإقفال أو حساسات السلامة ولو مؤقتًا', 'A', 3, NULL, NULL, 'A1', false, 1),
