  ('WABYS-OEQ-2026', 'ETF-Y1-K-01', 'OEQ-Y1-K', 'Occupational Safety & Health for Electrical and Electronic Work', 'السلامة والصحة المهنية في الأعمال الكهربية والإلكترونية', 'OSH concepts and the HSE management system; workplace lighting and ventilation; manual handling; PPE (head, face, eyes, hearing, respiratory, hands, feet, fall protection); fire triangle, fire classes and extinguisher types; safety signs; electrical hazards (shock, burns, arc flash, fire); rescuing a casualty from circuits below and above 1,000 V; the five safety rules and LOTO; ESD protection; ergonomics of computer work; first aid', 'معامل استنفاد الأوزون وقدرة الاحترار العالمي؛ إضاءة مكان العمل وتهويته؛ المناولة اليدوية؛ معدات الوقاية الشخصية (الرأس والوجه والعينين والسمع والتنفس واليدين والقدمين والحماية من السقوط)؛ مثلث الحريق وفئات الحرائق وأنواع الطفايات؛ علامات السلامة؛ المخاطر الكهربائية (الصدمة والحروق والقوس الكهربائي والحريق)؛ إنقاذ المصاب من دوائر أقل وأعلى من 1000 فولت؛ قواعد السلامة الخمس والإقفال ووضع البطاقات؛ تطبيق احتياطات التفريغ الكهروستاتيكي؛ بيئة العمل المريحة على الحاسب؛ الإسعافات الأولية', 'K', 1, 40, NULL, NULL, false, 1),
  ('WABYS-OEQ-2026', 'ETF-Y1-K-02', 'OEQ-Y1-K', 'DC Circuits & Passive Components', 'دوائر التيار المستمر والعناصر الخاملة', 'Charge, voltage, current, resistance, power; Ohm''s law; Kirchhoff''s current and voltage laws; current and voltage dividers; resistor types, color code, series/parallel/compound; LDR and NTC/PTC; fuses', 'يغطي فتحات المواسير؛ قانون أوم؛ حساب تكلفة العمل؛ مقسمات التيار والجهد؛ أنواع المقاومات وكود الألوان والتوالي والتوازي والمركب؛ جهاز قياس LCR؛ المصهرات', 'K', 1, 50, NULL, NULL, false, 2),
  ('WABYS-OEQ-2026', 'ETF-Y1-K-03', 'OEQ-Y1-K', 'AC Circuits, Capacitors, Inductors & Transformers', 'دوائر التيار المتردد والمكثفات والملفات والمحولات', 'Sinusoidal quantities; capacitors and coils (types, codes, series/parallel); charge/discharge and time constant; effect of AC on R, L and C; reactance and impedance; single-phase transformer principle and testing', 'الكميات الجيبية؛ المكثفات والملفات (الأنواع والأكواد والتوالي والتوازي)؛ الشحن والتفريغ والثابت الزمني؛ تأثير التيار المتردد على المقاومة والملف والمكثف؛ المفاعلة والمعاوقة؛ مبدأ المحول أحادي الوجه واختباره', 'K', 1, 40, NULL, NULL, false, 3),
  ('WABYS-OEQ-2026', 'ETF-Y1-K-04', 'OEQ-Y1-K', 'Analog Electronics Fundamentals', 'أساسيات الإلكترونيات التناظرية', 'Atom and semiconductors; PN junction, forward/reverse bias; diode characteristics; half- and full-wave rectifiers; Zener diode; LED; BJT operation, currents, parameters; BJT as switch; op-amp as inverting and non-inverting amplifier', 'الذرة وأشباه الموصلات؛ الوصلة الثنائية، الانحياز الأمامي والعكسي؛ خصائص الديود؛ موحدات نصف الموجة والموجة الكاملة؛ ديود زينر؛ المقاومة الضوئية والليد والديود الضوئي والترانزستور الضوئي والعازل الضوئي والثايرستور الضوئي؛ تشغيل الترانزستور ثنائي القطبية وتياراته ومعاملاته؛ الترانزستور ثنائي القطبية كمفتاح؛ مكبر العمليات كمكبر عاكس وغير عاكس', 'K', 1, 50, NULL, NULL, false, 4),
  ('WABYS-OEQ-2026', 'ETF-Y1-K-05', 'OEQ-Y1-K', 'Digital Electronics Fundamentals', 'أساسيات الإلكترونيات الرقمية', 'Decimal, binary, octal and hexadecimal systems; binary arithmetic; logic gates (AND, OR, NOT, NAND, NOR, XOR, XNOR); input/output interfaces; combinational logic (half adder, 2-bit comparator); sequential logic (SR latch, D and JK flip-flops)', 'نشرات البيانات وأدلة الصيانة؛ الحساب الثنائي؛ البوابات المنطقية (AND وOR وNOT وNAND وNOR وXOR وXNOR)؛ واجهات الإدخال والإخراج؛ المنطق التوافقي (نصف الجامع والمقارن ثنائي البت)؛ المنطق التتابعي (الماسك SR والقلابات D وJK)', 'K', 1, 40, NULL, NULL, false, 5),
  ('WABYS-OEQ-2026', 'ETF-Y1-K-06', 'OEQ-Y1-K', 'Test & Measurement Instruments', 'أجهزة الاختبار والقياس', 'Multimeter (AVO) and clamp meter; LCR meter; DC power supply; function generator; oscilloscope (controls, calibration, reading amplitude, period, phase); measurement categories (CAT II–IV); errors and tolerance; simulation software', 'بروتوكول مونتريال وتعديل كيغالي؛ أجهزة العرض LCD وDLP والليزر؛ التحكم في محرك التيار المستمر؛ مولد الموجات؛ راسم الموجات (أدوات التحكم والمعايرة وقراءة السعة والزمن الدوري والطور)؛ فئات القياس (CAT II–IV)؛ الأخطاء والسماحية؛ برامج المحاكاة', 'K', 1, 30, NULL, NULL, false, 6),
