  ('WABYS-AVE-2026', 'ETF-Y1-K-06', 'AVE-Y1-K', 'Test & Measurement Instruments', 'أجهزة الاختبار والقياس', 'Multimeter (AVO) and clamp meter; LCR meter; DC power supply; function generator; oscilloscope (controls, calibration, reading amplitude, period, phase); measurement categories (CAT II–IV); errors and tolerance; simulation software', 'بروتوكول مونتريال وتعديل كيغالي؛ أجهزة العرض LCD وDLP والليزر؛ التحكم في محرك التيار المستمر؛ مولد الموجات؛ راسم الموجات (أدوات التحكم والمعايرة وقراءة السعة والزمن الدوري والطور)؛ فئات القياس (CAT II–IV)؛ الأخطاء والسماحية؛ برامج المحاكاة', 'K', 1, 30, NULL, NULL, false, 6),
  ('WABYS-AVE-2026', 'CPM-03', 'AVE-Y1-K', 'Electrical Workshop Basics', 'أساسيات ورشة الكهرباء', 'Installation tools and tester screwdriver; clamp meter; stripping and jointing solid and stranded conductors; eyelets, lugs and ferrules; tinning; symbols and load types; lighting circuits (one-way, chandelier, two-way); sockets; SPST, SPDT and push-button control; relays and contactors (start/stop latch); fuses, MCBs, RCD/ELCB; earthing basics', 'أدلة التركيب؛ الأميتر الكلّابي؛ تعرية وربط الموصلات المصمتة والمجدولة؛ العيون والأطراف والجلب؛ القصدرة؛ الرموز وأنواع الأحمال؛ دوائر الإنارة (مفتاح واحد، نجفة، مفتاحان)؛ المقابس؛ التحكم بمفاتيح SPST وSPDT والضاغطات؛ الريليهات والكونتاكتورات (ماسك التشغيل والإيقاف)؛ المصهرات والقواطع الآلية وقواطع التسرب؛ أساسيات التأريض', 'K', 1, 50, NULL, NULL, false, 7),
  ('WABYS-AVE-2026', 'CPM-01', 'AVE-Y1-K', 'Computer & IT Principles', 'مبادئ الحاسب وتكنولوجيا المعلومات', 'Computer structure, classification and components; internet, browsers and e-mail; word processing (formatting, tables, images, proofing, page setup, printing); spreadsheets (formatting, formulas and functions, charts, print setup); presentations; WABYS additions: cloud storage and file management, password and MFA hygiene, safe use of AI assistants', 'محركات الضواغط؛ الإنترنت والمتصفحات والبريد الإلكتروني؛ معالجة النصوص (التنسيق والجداول والصور والتدقيق وإعداد الصفحة والطباعة)؛ جداول البيانات (التنسيق والمعادلات والدوال والرسوم البيانية وإعداد الطباعة)؛ العروض التقديمية؛ إضافات وابيز: التخزين السحابي وإدارة الملفات، ونظافة كلمات المرور والتحقق المتعدد، والاستخدام الآمن للمساعدات الذكية', 'K', 1, 54, NULL, NULL, false, 8),
